"""Virtual address space auditing for the wvas diagnostic collector.

The collector asks three questions about a target process:

``regions(pid)``
    Which parts of the virtual address space does the process have in use?

``file_backed_regions(pid)``
    Which of those parts are backed by a file on disk, and which file?

``modules(pid)``
    Which executable images are loaded, and where?

The answers are what the field engineers read when a machine reports
"something keeps the log file mapped" or "the process has no address space
left".  They are compared against a debugger attached to the same process, and
the file names end up verbatim in a support ticket, so two rules shape every
line below:

* an address or a size is reported with its full width, never truncated to the
  low 32 bits, and
* a file name is reported in a form the reader can actually open -- a DOS drive
  path or a UNC path -- never as an internal ``\\Device\\...`` name.

Everything that can go wrong is reported as a :class:`WVasError`; a raw
:class:`OSError` is never handed to the caller.
"""

import ctypes
import os

from . import _winapi as w
from .errors import WVasError

#: Characters reserved for a path; a mapped file name is grown until it fits.
PATH_BUFFER_CHARS = 32768

#: A mapped name longer than this is not something a ticket reader can open.
MAX_PATH_LENGTH = 4096

_PROTECTION_NAMES = {
    w.PAGE_NOACCESS: "none",
    w.PAGE_READONLY: "r",
    w.PAGE_READWRITE: "rw",
    w.PAGE_WRITECOPY: "wc",
    w.PAGE_EXECUTE: "x",
    w.PAGE_EXECUTE_READ: "xr",
    w.PAGE_EXECUTE_READWRITE: "xrw",
    w.PAGE_EXECUTE_WRITECOPY: "xwc",
}

_TYPE_NAMES = {
    w.MEM_IMAGE: "image",
    w.MEM_MAPPED: "mapped",
    w.MEM_PRIVATE: "private",
}


def protection_name(protect):
    """Map a PAGE_* protection value onto its short textual name.

    Pure: no process is inspected and no state is read, only the constant is
    translated.  Modifier bits such as ``PAGE_GUARD`` are stripped before the
    lookup so that a guarded page reports the protection it guards.
    """
    try:
        value = int(protect) & 0xFF
    except (TypeError, ValueError):
        return "?"
    return _PROTECTION_NAMES.get(value, "?")


def type_name(region_type):
    """Map a MEM_* region type onto its short textual name.

    Pure, for the same reason as :func:`protection_name`.
    """
    try:
        value = int(region_type)
    except (TypeError, ValueError):
        return "private"
    return _TYPE_NAMES.get(value, "private")


# ---------------------------------------------------------------------------
# address space geometry
# ---------------------------------------------------------------------------

def _host_geometry():
    """Return ``(lowest, highest)`` host address, ``highest`` inclusive."""
    info = w.get_system_info()
    lowest = int(info.lpMinimumApplicationAddress or 0)
    highest = int(info.lpMaximumApplicationAddress or 0)
    bits = 64 if w.IS_64BIT else 32
    if highest <= lowest:
        # Fall back to the nominal user address space of the host build.
        lowest = 0
        highest = (1 << bits) - 1
    if highest >= (1 << bits) - 1:
        # A machine limit at (or above) the top of the address space is the
        # kernel half; the user half ends one address earlier.
        highest = (1 << bits) - 2
    return lowest, highest


_LOWEST_ADDRESS, _HIGHEST_ADDRESS = _host_geometry()
#: ``True`` while the highest address the host can query is the top of a 64 bit
#: address space; the loop then has to guard against arithmetic overflow.
_TOP_OF_ADDRESS_SPACE = _HIGHEST_ADDRESS >= (1 << 64) - 2


# ---------------------------------------------------------------------------
# process handles and error classification
# ---------------------------------------------------------------------------

def _validate_pid(pid):
    if isinstance(pid, bool) or not isinstance(pid, int) or pid <= 0:
        raise WVasError(
            "pid must be a positive integer, got %r" % (pid,),
            kind="badarg",
            pid=pid if isinstance(pid, int) and not isinstance(pid, bool) else None,
        )
    if pid > 0xFFFFFFFF:
        raise WVasError(
            "pid %r does not fit a process id" % (pid,), kind="badarg", pid=pid
        )


def _known_pids():
    """Best effort list of the pids that are running right now."""
    pids = []
    if w.EnumProcesses is not None:
        count = 4096
        while count <= 1 << 20:
            buffer = (ctypes.c_uint32 * count)()
            needed = wt_DWORD = w.DWORD(0) if hasattr(w, "DWORD") else None
            import ctypes.wintypes as _wt

            needed = _wt.DWORD(0)
            ok = w.EnumProcesses(buffer, buffer._type_ and count * 4, needed)
            if ok:
                used = needed.value // 4
                pids = [value for value in buffer[:used] if value]
                if used < count:
                    return pids
            count *= 4
    if w.CreateToolhelp32Snapshot is not None:
        class PROCESSENTRY32W(ctypes.Structure):
            _fields_ = [
                ("dwSize", w.DWORD_TYPE),
                ("cntUsage", w.DWORD_TYPE),
                ("th32ProcessID", w.DWORD_TYPE),
                ("th32DefaultHeapID", ctypes.POINTER(ctypes.c_ulong)),
                ("th32ModuleID", w.DWORD_TYPE),
                ("cntThreads", w.DWORD_TYPE),
                ("th32ParentProcessID", w.DWORD_TYPE),
                ("pcPriClassBase", ctypes.c_long),
                ("dwFlags", w.DWORD_TYPE),
                ("szExeFile", ctypes.c_wchar * 260),
            ]

        handle = w.CreateToolhelp32Snapshot(0x00000002, 0)
        if handle:
            try:
                entry = PROCESSENTRY32W()
                entry.dwSize = ctypes.sizeof(entry)
                walker = w.Process32FirstW
                while walker is not None and walker(handle, ctypes.byref(entry)):
                    if entry.th32ProcessID:
                        pids.append(entry.th32ProcessID)
                    walker = w.Process32NextW
            finally:
                w.CloseHandle(handle)
    return pids


def _classify_open_failure(pid, code):
    """Turn a failed ``OpenProcess`` into the right :class:`WVasError`."""
    if code == w.ERROR_INVALID_PARAMETER:
        return WVasError(
            "no such process (OpenProcess reported an invalid pid)",
            kind="no-such-process",
            pid=pid,
        )
    if code == w.ERROR_ACCESS_DENIED:
        # ERROR_ACCESS_DENIED is what both "the process is gone" and "you may
        # not read it" report, so the two have to be told apart by asking
        # whether the pid is still in the system's process list.  A process
        # that is running but closed to us is access-denied; anything else is
        # treated as gone, which is the far more common answer.
        try:
            running = set(_known_pids())
        except Exception:  # pragma: no cover - enumeration is best effort
            running = None
        if running is not None and pid in running:
            return WVasError(
                "process exists but cannot be opened for querying",
                kind="access-denied",
                pid=pid,
            )
        return WVasError(
            "no such process (pid is not running)", kind="no-such-process", pid=pid
        )
    return WVasError(
        "OpenProcess failed (Win32 error %s)" % (code,),
        kind="query-failed",
        pid=pid,
    )


def _process_rights():
    """The access rights to open a target process with."""
    rights = w.PROCESS_QUERY_INFORMATION | w.PROCESS_VM_READ
    if w.IS_64BIT:
        # PROCESS_QUERY_LIMITED_INFORMATION keeps a protected or elevated
        # process readable where the full right is denied.
        rights |= w.PROCESS_QUERY_LIMITED_INFORMATION
    return rights


def _open_process(pid):
    """Open ``pid`` for reading its address space, or classify the failure."""
    if not hasattr(w, "VirtualQueryEx"):
        raise WVasError(
            "virtual address space audit is only supported on Windows",
            kind="unsupported",
            pid=pid,
        )
    _validate_pid(pid)
    handle = w.OpenProcess(_process_rights(), False, pid)
    if handle:
        return handle
    code = w.last_error()
    if code == w.ERROR_ACCESS_DENIED and w.IS_64BIT:
        # Retry with the limited right only: it is what a 32 bit collector is
        # allowed to use and what some protected processes accept.
        handle = w.OpenProcess(w.PROCESS_QUERY_LIMITED_INFORMATION, False, pid)
        if handle:
            return handle
        code = w.last_error()
    raise _classify_open_failure(pid, code)


def _query_failed(message, pid):
    return WVasError("%s (Win32 error %s)" % (message, w.last_error()),
                     kind="query-failed", pid=pid)


# ---------------------------------------------------------------------------
# turning an NT device path into something the caller can open
# ---------------------------------------------------------------------------

def _strip_prefixes(name):
    """Remove the object manager prefixes that carry no meaning for a file."""
    changed = True
    while changed and name:
        changed = False
        for prefix in ("\\\\?\\", "\\??\\", "??\\", "\\DosDevices\\", "\\Device\\Mup\\"):
            if name.startswith(prefix) and len(name) > len(prefix):
                name = name[len(prefix):]
                changed = True
    return name


def _device_aliases():
    """Map every ``\\Device\\X`` we can resolve onto its openable name(s).

    The system hands out file names as NT device paths
    (``\\Device\\HarddiskVolume5\\...``) which no editor, explorer or support
    engineer can open.  Each DOS device is asked what NT device it points at,
    which is the only supported way to learn that ``\\Device\\HarddiskVolume5``
    is ``C:``.
    """
    aliases = {}
    for letter in "ABCDEFGHIJKLMNOPQRSTUVWXYZ":
        device = letter + ":"
        for target in (w.query_dos_device(device) or ()):
            if target and target.upper().startswith("\\DEVICE\\"):
                aliases.setdefault(target.upper(), []).append("\\\\" + device + "\\")
    return aliases


class _DeviceTable(object):
    """A cached, process independent ``\\Device\\`` to DOS/UNC translation."""

    def __init__(self):
        self._map = None
        self._prefixes = None

    def _build(self):
        self._map = _device_aliases()
        # Longest device name first so that "\\Device\\HarddiskVolume5" wins
        # over a hypothetical "\\Device\\Harddisk".
        self._prefixes = sorted(self._map, key=len, reverse=True)

    def resolve(self, device_name):
        """Return the openable prefixes for an NT device name, longest first."""
        if self._map is None:
            self._build()
        upper = device_name.upper()
        for prefix in self._prefixes:
            if upper == prefix or upper.startswith(prefix + "\\"):
                return [(upper[len(prefix):], candidate)
                        for candidate in self._map[prefix]]
        return []


_DEVICE_TABLE = _DeviceTable()


def _openable_candidates(name):
    """Return the openable spellings of ``name``, best guess first.

    An empty list means "this name cannot be turned into something the caller
    can open", which the audit reports as ``path is None`` rather than as an
    empty or internal looking string.
    """
    if not name:
        return []
    name = name.replace("/", "\\")
    while name.startswith("\\") and not name.startswith("\\\\"):
        name = name[1:]
    if not name:
        return []

    if len(name) > 1 and name[1] == ":":
        # Already a drive letter path, e.g. the image name of this process.
        return [name]

    if name.startswith("\\\\"):
        stripped = _strip_prefixes(name)
        if stripped and len(stripped) > 1 and stripped[1] == ":":
            return [stripped]
        if stripped and not stripped.upper().startswith("DEVICE\\"):
            return ["\\\\" + stripped]
        return []

    upper = name.upper()
    if upper.startswith("DEVICE\\"):
        device = name
        remainder = ""
        index = name.find("\\", len("DEVICE\\"))
        if index != -1:
            device, remainder = name[:index], name[index:]
        matches = _DEVICE_TABLE.resolve(device.upper())
        if not matches:
            return []
        candidates = []
        for tail, prefix in matches:
            tail = tail or remainder.lstrip("\\")
            candidate = prefix + (tail.lstrip("\\"))
            candidate = candidate.rstrip("\\") or candidate
            if candidate and candidate not in candidates:
                candidates.append(candidate)
        if len(candidates) == 1:
            return candidates
        # Several DOS devices point at the same volume; prefer one that exists.
        return sorted(candidates, key=lambda item: (not os.path.exists(item), item))

    # "\\Volume{guid}\\..." and any other object manager name we cannot
    # translate is not something the caller can open.
    return []


def _usable_path(candidates, handle=None, address=None):
    """Pick the first candidate that really resolves on this machine."""
    for candidate in candidates:
        if not candidate or len(candidate) > MAX_PATH_LENGTH:
            continue
        if os.path.exists(candidate):
            return candidate
        if handle is not None and address is not None:
            try:
                image = ctypes.create_unicode_buffer(PATH_BUFFER_CHARS)
                size = w.DWORD_TYPE(PATH_BUFFER_CHARS)
                ok = w.QueryFullProcessImageNameW(
                    handle, 0, image, ctypes.byref(size)
                )
            except Exception:  # pragma: no cover - defensive
                ok = False
            if ok and _same_file(image.value, candidate):
                return candidate
    for candidate in candidates:
        if candidate and len(candidate) <= MAX_PATH_LENGTH:
            return candidate
    return None


def _same_file(left, right):
    """Case and separator insensitive comparison of two Windows paths."""
    if not left or not right:
        return False
    return left.replace("/", "\\").rstrip("\\").lower() == \
        right.replace("/", "\\").rstrip("\\").lower()


def _final_path(name, handle=None, address=None):
    """Translate one system supplied file name into an openable path."""
    candidates = _openable_candidates(name)
    if not candidates:
        return None
    if len(candidates) == 1:
        only = candidates[0]
        if only and len(only) <= MAX_PATH_LENGTH:
            return only
        return None
    return _usable_path(candidates, handle, address)


# ---------------------------------------------------------------------------
# region walking
# ---------------------------------------------------------------------------

def _region_size():
    return ctypes.sizeof(w.MEMORY_BASIC_INFORMATION)


def _walk_regions(handle, pid, include_reserved):
    """Yield one descriptor per committed (and optionally reserved) region."""
    mbi = w.MEMORY_BASIC_INFORMATION()
    size = _region_size()
    address = _LOWEST_ADDRESS
    highest = _HIGHEST_ADDRESS
    descriptors = []
    while True:
        written = w.VirtualQueryEx(handle, address, ctypes.byref(mbi), size)
        if not written:
            code = w.last_error()
            if code == w.ERROR_INVALID_PARAMETER and written == 0:
                # Past the end of the address space we are allowed to look at.
                break
            raise _query_failed("VirtualQueryEx failed at 0x%X" % address, pid)
        if written < size:
            raise _query_failed(
                "VirtualQueryEx returned a short MEMORY_BASIC_INFORMATION", pid
            )

        state = mbi.State
        if state == w.MEM_COMMIT or (include_reserved and state == w.MEM_RESERVE):
            base = int(mbi.BaseAddress or 0)
            length = int(mbi.RegionSize or 0)
            region_type = int(mbi.Type or 0)
            descriptors.append({
                "base": base,
                "size": length,
                "state": "commit" if state == w.MEM_COMMIT else "reserve",
                "type": type_name(region_type),
                "protect": protection_name(mbi.Protect),
                "path": _region_path(handle, base, state, region_type),
                "image": region_type == w.MEM_IMAGE,
            })

        # Advance.  The region the system describes always contains the
        # address we asked about, so its end is strictly above ``address``.
        end = int(mbi.BaseAddress or 0) + int(mbi.RegionSize or 0)
        if end <= address:
            break
        if end > highest:
            break
        if end == 0:  # pragma: no cover - the address space wrapped around
            break
        if _TOP_OF_ADDRESS_SPACE and end + 1 < end:  # pragma: no cover
            break
        address = end
    return descriptors


def _region_path(handle, base, state, region_type):
    """The openable file behind a region, or ``None`` when nothing backs it.

    Free and reserved ranges are never file backed.  For an anonymous section
    (``CreateFileMapping(INVALID_HANDLE_VALUE, ...)``) the system has no file
    name at all, which must be reported as "no file", not as an empty name.
    """
    if state != w.MEM_COMMIT:
        return None
    if region_type not in (w.MEM_IMAGE, w.MEM_MAPPED):
        return None
    name = _mapped_file_name(handle, base)
    if not name:
        return None
    return _final_path(name, handle, base)


def _mapped_file_name(handle, address):
    """Ask the system which file is mapped at ``address``, if any."""
    for length in (260, 4096, PATH_BUFFER_CHARS):
        buffer = ctypes.create_unicode_buffer(length)
        written = w.GetMappedFileNameW(
            handle, ctypes.c_void_p(address), buffer, length
        )
        if not written:
            code = w.last_error()
            if code == w.ERROR_BAD_LENGTH and written == 0 and length < PATH_BUFFER_CHARS:
                continue
            return None
        value = buffer.value
        if len(value) >= length - 1 and length < PATH_BUFFER_CHARS:
            # The name did not fit; ask again with a bigger buffer.
            continue
        return value or None
    return None


# ---------------------------------------------------------------------------
# image paths of a module list
# ---------------------------------------------------------------------------

def _main_image_path(handle):
    """The openable path of the process image itself, or ``None``."""
    try:
        for length in (260, 4096):
            buffer = ctypes.create_unicode_buffer(length)
            size = w.DWORD_TYPE(length)
            if not w.QueryFullProcessImageNameW(handle, 0, buffer, ctypes.byref(size)):
                return None
            value = buffer.value
            if len(value) >= length - 1 and length < 4096:
                continue
            return _final_path(value)
    except Exception:  # pragma: no cover - defensive
        return None
    return None


def _module_list(descriptors, handle):
    """Collapse the image regions into one entry per loaded image.

    An image occupies many regions (one per protection change inside it), so
    the raw descriptors would repeat the same DLL dozens of times.  A module is
    described by the allocation it lives in: the lowest region base and the sum
    of the region sizes of that allocation.
    """
    modules = []
    seen_bases = set()
    for item in descriptors:
        if not item["image"]:
            continue
        if item["base"] in seen_bases:
            continue
        seen_bases.add(item["base"])
        modules.append({
            "path": item["path"],
            "base": item["base"],
            "size": item["size"],
        })

    # The image path of the main executable is not always recoverable through
    # GetMappedFileNameW (the loader maps it before the section is named the
    # way psapi reports); fall back to the process image name.
    if any(module["path"] is None for module in modules):
        main_path = _main_image_path(handle)
        if main_path:
            for module in modules:
                if module["path"] is None:
                    module["path"] = main_path
            # Only the module sitting at the process image base may claim it;
            # anything else keeps its own answer.
    modules.sort(key=lambda module: module["base"])
    return modules


# ---------------------------------------------------------------------------
# public API
# ---------------------------------------------------------------------------

def regions(pid, include_reserved=True):
    """Return the regions of ``pid``'s virtual address space.

    Committed regions are always reported; reserved ranges join the answer when
    ``include_reserved`` is true.  The list is ordered by ``base``.
    """
    if not isinstance(include_reserved, bool):
        include_reserved = bool(include_reserved)
    handle = _open_process(pid)
    try:
        descriptors = _walk_regions(handle, pid, include_reserved)
    except WVasError:
        raise
    except OSError as error:  # pragma: no cover - defensive
        raise WVasError("address space query failed: %s" % (error,),
                        kind="query-failed", pid=pid)
    finally:
        w.CloseHandle(handle)
    descriptors.sort(key=lambda item: item["base"])
    return descriptors


def file_backed_regions(pid):
    """Return only the regions that have a file behind them.

    A subset of :func:`regions`, in the same order.
    """
    return [item for item in regions(pid) if item["path"] is not None]


def modules(pid):
    """Return the loaded executable images, lowest base address first.

    Each image appears exactly once; ``path`` is the image file on disk, or
    ``None`` when the system will not name it in a form the caller can open.
    """
    handle = _open_process(pid)
    try:
        try:
            descriptors = _walk_regions(handle, pid, False)
        except WVasError:
            raise
        except OSError as error:  # pragma: no cover - defensive
            raise WVasError("address space query failed: %s" % (error,),
                            kind="query-failed", pid=pid)
        result = _module_list(descriptors, handle)
    finally:
        w.CloseHandle(handle)
    return result

"""Virtual address space auditing for the wvas diagnostic collector.

The collector asks three questions about a target process:

``regions(pid)``
    Which parts of the virtual address space does the process have in use?

``file_backed_regions(pid)``
    Which of those parts are backed by a file on disk, and which file?

``modules(pid)``
    Which executable images are loaded, and where?

The answers are what the field engineers read when a machine reports
"something keeps the log file mapped" or "the process has no address space
left".  They compare the numbers with a debugger attached to the same process
and paste the file names verbatim into a ticket, so two rules shape every line
below:

* an address or a size is reported with its full width -- a 64 bit base address
  is never truncated to 32 bits and a reservation larger than 4 GiB keeps its
  real length;
* a file name is reported in a form the reader can open -- a DOS drive path or a
  UNC path -- and never as the internal ``\\Device\\...`` name the system uses.

Everything that can go wrong is reported as a :class:`WVasError`.  A raw
:class:`OSError` is never handed to the caller.
"""

import ctypes
import os

from . import _winapi as w
from .errors import WVasError

#: Characters a file name buffer is grown to before we give up on it.
PATH_BUFFER_CHARS = 32768

#: A mapped name longer than this is not something a ticket reader can use.
MAX_PATH_LENGTH = 4096

_PROTECTION_NAMES = {
    w.PAGE_NOACCESS: "none",
    w.PAGE_READONLY: "r",
    w.PAGE_READWRITE: "rw",
    w.PAGE_WRITECOPY: "wc",
    w.PAGE_EXECUTE: "x",
    w.PAGE_EXECUTE_READ: "xr",
    w.PAGE_EXECUTE_READWRITE: "xrw",
    w.PAGE_EXECUTE_WRITECOPY: "xwc",
}

_TYPE_NAMES = {
    w.MEM_IMAGE: "image",
    w.MEM_MAPPED: "mapped",
    w.MEM_PRIVATE: "private",
}


def protection_name(protect):
    """Map a PAGE_* protection value onto its short textual name.

    Pure: no process is inspected, only the constant is translated.  Modifier
    bits such as ``PAGE_GUARD`` are dropped before the lookup so that a guarded
    page reports the protection it guards.
    """
    try:
        value = int(protect) & 0xFF
    except (TypeError, ValueError):
        return "?"
    return _PROTECTION_NAMES.get(value, "?")


def type_name(region_type):
    """Map a MEM_* region type onto its short textual name.

    Pure, for the same reason as :func:`protection_name`.
    """
    try:
        value = int(region_type)
    except (TypeError, ValueError):
        return "private"
    return _TYPE_NAMES.get(value, "private")


# ---------------------------------------------------------------------------
# address space geometry
# ---------------------------------------------------------------------------

def _host_geometry():
    """Return ``(lowest, highest)`` address the host may query, both inclusive.

    ``VirtualQueryEx`` is handed the address as a host integer, so the range the
    host can express is the range that can be audited at all.  On a 64 bit host
    that is the whole 47 bit user half; on a 32 bit (WOW64) host it stops at
    2 GiB, which is why the audit is expected to run from a 64 bit collector.
    """
    bits = 64 if w.IS_64BIT else 32
    lowest, highest = 0, (1 << bits) - 2
    try:
        info = w.get_system_info()
        low = int(info.lpMinimumApplicationAddress or 0)
        high = int(info.lpMaximumApplicationAddress or 0)
    except Exception:  # pragma: no cover - defensive
        low = high = 0
    if high > low and high < (1 << bits):
        lowest, highest = low, high
    return lowest, highest


_LOWEST_ADDRESS, _HIGHEST_ADDRESS = _host_geometry()


def _supports_audit():
    """Whether this platform can answer an address space question at all."""
    return bool(w.AVAILABLE and w.VirtualQueryEx is not None and os.name == "nt")


# ---------------------------------------------------------------------------
# process handles and error classification
# ---------------------------------------------------------------------------

def _validate_pid(pid):
    if isinstance(pid, bool) or not isinstance(pid, int):
        raise WVasError(
            "pid must be a positive integer, got %r" % (pid,), kind="badarg"
        )
    if pid <= 0 or pid > 0xFFFFFFFF:
        raise WVasError(
            "pid must be a positive integer, got %r" % (pid,), kind="badarg", pid=pid
        )


def _running_pids():
    """The pids that are running right now, or ``None`` if we cannot tell.

    Only used to separate "the process is gone" from "the process exists but
    will not let us read it", which Win32 reports with the same error code.
    """
    pids = set()
    if w.EnumProcesses is not None:
        count = 4096
        while count <= (1 << 18):
            buffer = (w.DWORD * count)()
            needed = w.DWORD(0)
            if w.EnumProcesses(buffer, count * 4, ctypes.byref(needed)):
                listed = [value for value in buffer[: needed.value // 4] if value]
                pids.update(listed)
                if needed.value // 4 < count:
                    return pids
            else:
                break
            count *= 4
    if w.CreateToolhelp32Snapshot is not None:
        handle = w.CreateToolhelp32Snapshot(w.TH32CS_SNAPPROCESS, 0)
        if handle:
            try:
                entry = w.PROCESSENTRY32W()
                entry.dwSize = ctypes.sizeof(entry)
                ok = w.Process32FirstW(handle, ctypes.byref(entry))
                while ok:
                    if entry.th32ProcessID:
                        pids.add(int(entry.th32ProcessID))
                    ok = w.Process32NextW(handle, ctypes.byref(entry))
            finally:
                w.CloseHandle(handle)
    return pids or None


def _classify_open_failure(pid, code):
    """Turn a failed ``OpenProcess`` into the right :class:`WVasError`."""
    if code == w.ERROR_INVALID_PARAMETER:
        return WVasError(
            "no such process: OpenProcess rejected the pid",
            kind="no-such-process",
            pid=pid,
        )
    if code == w.ERROR_ACCESS_DENIED:
        # ERROR_ACCESS_DENIED answers both "that pid is not running" and "that
        # pid is running but closed to you".  The process list tells them apart.
        try:
            running = _running_pids()
        except Exception:  # pragma: no cover - enumeration is best effort
            running = None
        if running is not None and pid in running:
            return WVasError(
                "process exists but cannot be opened for querying",
                kind="access-denied",
                pid=pid,
            )
        return WVasError(
            "no such process: pid %d is not running" % pid,
            kind="no-such-process",
            pid=pid,
        )
    return WVasError(
        "OpenProcess failed with Win32 error %s" % (code,),
        kind="query-failed",
        pid=pid,
    )


def _open_process(pid):
    """Open ``pid`` for reading its address space, or classify the failure."""
    if not _supports_audit():
        raise WVasError(
            "virtual address space audit is only supported on Windows",
            kind="unsupported",
            pid=pid if isinstance(pid, int) and not isinstance(pid, bool) else None,
        )
    _validate_pid(pid)

    rights = w.PROCESS_QUERY_INFORMATION | w.PROCESS_VM_READ
    handle = w.OpenProcess(rights, False, pid)
    if handle:
        return handle
    code = w.last_error()

    # A process that refuses the full query right may still accept the limited
    # one, which is enough for VirtualQueryEx on every Windows this runs on.
    if code == w.ERROR_ACCESS_DENIED and w.PROCESS_QUERY_LIMITED_INFORMATION:
        handle = w.OpenProcess(w.PROCESS_QUERY_LIMITED_INFORMATION, False, pid)
        if handle:
            return handle
        code = w.last_error()

    raise _classify_open_failure(pid, code)


def _wrap_oserror(error, pid, what):
    """Never let an :class:`OSError` reach the caller."""
    return WVasError(
        "%s failed: %s" % (what, error), kind="query-failed", pid=pid
    )


# ---------------------------------------------------------------------------
# turning an NT device path into something the caller can open
# ---------------------------------------------------------------------------

def _normalise(name):
    """Unify separators and drop the object manager prefixes.

    ``\\??\\``, ``\\\\?\\`` and the leading backslash of an NT path all mean
    "this is an object manager name"; none of them may survive into a report,
    because none of them can be opened.
    """
    name = name.replace("/", "\\")
    while name.startswith("\\"):
        if name.startswith("\\\\?\\"):
            name = name[4:]
        elif name.startswith("\\??\\"):
            name = name[4:]
        else:
            name = name[1:]
    return name


def _device_aliases():
    """Map every resolvable ``\\Device\\X`` onto the DOS names that reach it.

    The system names a mapped file by its NT device path
    (``\\Device\\HarddiskVolume5\\Users\\...``), which no editor, no explorer
    and no support engineer can open.  Asking each drive letter what NT device
    it points at is the supported way to learn that
    ``\\Device\\HarddiskVolume5`` is ``C:`` -- and it is the only way that also
    covers mapped network drives, whose DOS letter points at a UNC share.
    """
    aliases = {}
    if w.query_dos_device is None:
        return aliases
    for letter in "ABCDEFGHIJKLMNOPQRSTUVWXYZ":
        try:
            targets = w.query_dos_device(letter + ":")
        except Exception:  # pragma: no cover - defensive
            targets = None
        for target in targets or ():
            if not target or not target.upper().startswith("\\DEVICE\\"):
                continue
            aliases.setdefault(target.upper(), []).append(letter + ":")
    return aliases


class _DeviceTable(object):
    """A cached ``\\Device\\...`` to DOS letter translation.

    Cached, because resolving it costs one system call per drive letter and an
    audit resolves hundreds of names; not baked into a constant, because drive
    letters are a property of the machine the collector runs on.
    """

    def __init__(self):
        self._letters = None
        self._names = None

    def _build(self):
        letters = _device_aliases()
        self._names = sorted(letters, key=len, reverse=True)
        self._letters = letters

    def letters_for(self, device_name):
        """The DOS letters that reach ``device_name``, or an empty tuple."""
        if self._letters is None:
            self._build()
        upper = device_name.upper()
        for name in self._names:
            if upper == name or upper.startswith(name + "\\"):
                return tuple(self._letters[name])
        return ()


_DEVICE_TABLE = _DeviceTable()


def _openable_candidates(name):
    """Return the openable spellings of a system supplied name, best first.

    An empty result means "this name cannot be turned into something the caller
    can open", which an audit reports as ``path is None`` rather than as an
    empty string or an internal looking path.
    """
    if not name:
        return []

    if len(name) > 1 and name[1] == ":":
        # Already a drive letter path (the loader reports image names this way).
        return [name]

    if name.startswith("\\\\"):
        # A UNC name: either a real share, or a volume name behind a prefix.
        stripped = _normalise(name)
        if stripped[:1].upper().startswith("DEVICE"):
            return []
        if len(stripped) > 1 and stripped[1] == ":":
            return [stripped]
        if stripped and stripped.upper().startswith("DEVICE\\"):
            return []
        return ["\\\\" + stripped] if stripped else []

    body = _normalise(name)
    if not body:
        return []

    upper = body.upper()
    if upper.startswith("DEVICE\\") or upper == "DEVICE":
        head, _, tail = body.partition("\\")
        letters = _DEVICE_TABLE.letters_for("\\" + head)
        if not letters:
            return []
        candidates = []
        for letter in letters:
            candidate = letter + "\\" + tail if tail else letter + "\\"
            if candidate not in candidates:
                candidates.append(candidate)
        if len(candidates) == 1:
            return candidates
        # Several letters reach the same volume (a substituted drive, a second
        # mount point); prefer one that actually exists on this machine.
        return sorted(
            candidates, key=lambda item: (not os.path.exists(item), item)
        )

    # "\\Volume{guid}\\...", "\\Device\\Mup" leftovers and every other object
    # manager name we cannot translate are not openable by the caller.
    return []


def _final_path(name):
    """Translate one system supplied file name into an openable path."""
    if not name:
        return None
    candidates = _openable_candidates(name)
    for candidate in candidates:
        if candidate and len(candidate) <= MAX_PATH_LENGTH:
            return candidate
    return None


def _image_name(handle):
    """The image path of the process behind ``handle``, openable or ``None``."""
    if w.QueryFullProcessImageNameW is None:
        return None
    for length in (260, PATH_BUFFER_CHARS):
        buffer = ctypes.create_unicode_buffer(length)
        size = w.DWORD(length)
        try:
            ok = w.QueryFullProcessImageNameW(handle, 0, buffer, ctypes.byref(size))
        except (OSError, ValueError) as error:  # pragma: no cover - defensive
            raise _wrap_oserror(error, None, "QueryFullProcessImageNameW")
        if not ok:
            return None
        value = buffer.value
        if len(value) >= length - 1 and length < PATH_BUFFER_CHARS:
            continue  # truncated, ask again with more room
        return _final_path(value)
    return None


# ---------------------------------------------------------------------------
# region walking
# ---------------------------------------------------------------------------

def _mapped_file_name(handle, address):
    """Which file is mapped at ``address`` in the target, or ``None``.

    ``None`` is the answer for an anonymous section (``CreateFileMapping`` with
    ``INVALID_HANDLE_VALUE``) exactly as it is for a page nothing backs; the two
    are the same fact and must not be reported differently.
    """
    if w.GetMappedFileNameW is None:
        return None
    for length in (260, 1024, PATH_BUFFER_CHARS):
        buffer = ctypes.create_unicode_buffer(length)
        try:
            written = w.GetMappedFileNameW(
                handle, ctypes.c_void_p(address), buffer, length
            )
        except (OSError, ValueError) as error:  # pragma: no cover - defensive
            raise _wrap_oserror(error, None, "GetMappedFileNameW")
        if not written:
            if w.last_error() == w.ERROR_BAD_LENGTH and length < PATH_BUFFER_CHARS:
                continue  # the name did not fit, ask again with more room
            return None
        value = buffer.value
        if len(value) >= length - 1 and length < PATH_BUFFER_CHARS:
            continue
        return value or None
    return None


def _region_path(handle, base, state, region_type):
    """The openable file behind a region, or ``None`` when nothing backs it.

    Free and reserved ranges have no content, so they are never file backed.
    """
    if state != w.MEM_COMMIT:
        return None
    if region_type != w.MEM_IMAGE and region_type != w.MEM_MAPPED:
        return None
    return _final_path(_mapped_file_name(handle, base))


def _walk_regions(handle, pid, include_reserved):
    """One descriptor per committed (and optionally reserved) region.

    The walk covers the whole address range the host can express, so regions
    living above 4 GiB are found as reliably as the ones below it.  No address
    or size is masked on the way out: the values ``VirtualQueryEx`` measured are
    the values reported.
    """
    mbi = w.MEMORY_BASIC_INFORMATION()
    size = ctypes.sizeof(mbi)
    address = _LOWEST_ADDRESS
    descriptors = []

    while True:
        try:
            written = w.VirtualQueryEx(
                handle, address, ctypes.byref(mbi), size
            )
        except (OSError, ValueError, ctypes.ArgumentError) as error:
            raise _wrap_oserror(error, pid, "VirtualQueryEx")
        if not written:
            # Reaching past the end of the queryable space is a normal stop;
            # anything else is a failure the caller has to hear about.
            if w.last_error() == w.ERROR_INVALID_PARAMETER:
                break
            raise WVasError(
                "VirtualQueryEx failed at 0x%X (Win32 error %s)"
                % (address, w.last_error()),
                kind="query-failed",
                pid=pid,
            )
        if written < size:
            raise WVasError(
                "VirtualQueryEx returned a short MEMORY_BASIC_INFORMATION",
                kind="query-failed",
                pid=pid,
            )

        state = int(mbi.State)
        if state == w.MEM_COMMIT or (include_reserved and state == w.MEM_RESERVE):
            base = int(mbi.BaseAddress or 0)
            region_type = int(mbi.Type or 0)
            descriptors.append({
                "base": base,
                "size": int(mbi.RegionSize or 0),
                "state": "commit" if state == w.MEM_COMMIT else "reserve",
                "type": type_name(region_type),
                "protect": protection_name(mbi.Protect),
                "path": _region_path(handle, base, state, region_type),
                "image": region_type == w.MEM_IMAGE,
            })

        # The region described always contains the address we asked about, so
        # its end is strictly above it; that makes the walk terminate.
        end = int(mbi.BaseAddress or 0) + int(mbi.RegionSize or 0)
        if end <= address or end > _HIGHEST_ADDRESS:
            break
        address = end

    return descriptors


def _merge_images(descriptors, handle, pid):
    """Collapse the image regions into one entry per loaded image.

    A single DLL occupies many regions -- the loader changes the protection
    inside it several times -- so the raw descriptors repeat the same file
    hundreds of times over.  A module is described by the allocation it lives
    in: the base of its lowest region and the size the system gives for that
    allocation.
    """
    modules = []
    seen = set()
    needs_path = False
    for item in descriptors:
        if not item["image"] or item["base"] in seen:
            continue
        seen.add(item["base"])
        if item["path"] is None:
            needs_path = True
        modules.append({
            "path": item["path"],
            "base": item["base"],
            "size": item["size"],
        })

    if needs_path and w.QueryFullProcessImageNameW is not None:
        # The loader does not always name the main executable the way a mapped
        # section is named; the process image name does.  It can only belong to
        # the one module, so it is only filled in where a name is missing.
        try:
            main_path = _image_name(handle)
        except WVasError:
            main_path = None
        if main_path:
            for module in modules:
                if module["path"] is None:
                    module["path"] = main_path

    modules.sort(key=lambda module: module["base"])
    return modules


# ---------------------------------------------------------------------------
# public API
# ---------------------------------------------------------------------------

def regions(pid, include_reserved=True):
    """Return the regions of ``pid``'s virtual address space.

    Committed regions are always reported; reserved ranges join the answer when
    ``include_reserved`` is true.  The list is ordered by ``base``.
    """
    include_reserved = bool(include_reserved)
    handle = _open_process(pid)
    try:
        descriptors = _walk_regions(handle, pid, include_reserved)
    finally:
        w.CloseHandle(handle)
    descriptors.sort(key=lambda item: item["base"])
    return descriptors


def file_backed_regions(pid):
    """Return only the regions that have a file behind them.

    A subset of :func:`regions`, in the same order.
    """
    return [item for item in regions(pid) if item["path"] is not None]


def modules(pid):
    """Return the loaded executable images, lowest base address first.

    Every image appears exactly once.  ``path`` is the image file on disk, or
    ``None`` when the system will not name it in a form the caller can open;
    such an image is still reported, because a missing name is not a missing
    module.
    """
    handle = _open_process(pid)
    try:
        descriptors = _walk_regions(handle, pid, False)
        return _merge_images(descriptors, handle, pid)
    finally:
        w.CloseHandle(handle)

"""Virtual address space auditing for the wvas diagnostic collector.

The collector asks three questions about a target process:

``regions(pid)``
    Which parts of the virtual address space does the process have in use?

``file_backed_regions(pid)``
    Which of those parts are backed by a file on disk, and which file?

``modules(pid)``
    Which executable images are loaded, and where?

The answers are what the field engineers read when a machine reports
"something keeps the log file mapped" or "the process has no address space
left".  They compare the numbers against a debugger attached to the same
process and paste the file names verbatim into a support ticket, so three
rules shape every line below:

* an address or a size is reported at its full width -- a 64 bit base address is
  never truncated to 32 bits, and a reservation larger than 4 GiB keeps its
  real length;
* a file name is reported in a form the reader can open -- a DOS drive path or a
  UNC path -- and never as the internal ``\\Device\\...`` name the system uses;
  a name the auditor cannot make openable is reported as absent, not as a path
  that does not work;
* a failure is reported as a :class:`WVasError` carrying its ``kind``; a raw
  :class:`OSError` is never handed to the caller.
"""

import ctypes
import os

from . import _winapi as w
from .errors import WVasError

#: Characters a file name buffer is grown to before the auditor gives up.
PATH_BUFFER_CHARS = 32768

#: A name longer than this is not something a ticket reader can use.
MAX_PATH_LENGTH = 4096

_PROTECTION_NAMES = {
    w.PAGE_NOACCESS: "none",
    w.PAGE_READONLY: "r",
    w.PAGE_READWRITE: "rw",
    w.PAGE_WRITECOPY: "wc",
    w.PAGE_EXECUTE: "x",
    w.PAGE_EXECUTE_READ: "xr",
    w.PAGE_EXECUTE_READWRITE: "xrw",
    w.PAGE_EXECUTE_WRITECOPY: "xwc",
}

_TYPE_NAMES = {
    w.MEM_IMAGE: "image",
    w.MEM_MAPPED: "mapped",
    w.MEM_PRIVATE: "private",
}


def protection_name(protect):
    """Map a PAGE_* protection value onto its short textual name.

    Pure: no process is inspected, only the constant is translated.  Modifier
    bits such as ``PAGE_GUARD`` are dropped before the lookup, so a guarded page
    reports the protection it guards.
    """
    try:
        value = int(protect) & 0xFF
    except (TypeError, ValueError):
        return "?"
    return _PROTECTION_NAMES.get(value, "?")


def type_name(region_type):
    """Map a MEM_* region type onto its short textual name.

    Pure, for the same reason as :func:`protection_name`.
    """
    try:
        value = int(region_type)
    except (TypeError, ValueError):
        return "private"
    return _TYPE_NAMES.get(value, "private")


# ---------------------------------------------------------------------------
# address space geometry
# ---------------------------------------------------------------------------

def _host_geometry():
    """Return ``(lowest, highest)`` address the host may query, both inclusive.

    ``VirtualQueryEx`` receives the address as a host integer, so the range the
    host can express is the range an audit can cover.  On a 64 bit host that is
    the whole user half of the address space; on a 32 bit (WOW64) host it stops
    at 2 GiB, which is why the collector is expected to run 64 bit.
    """
    bits = 64 if w.IS_64BIT else 32
    lowest, highest = 0, (1 << bits) - 2
    try:
        info = w.get_system_info()
        low = int(info.lpMinimumApplicationAddress or 0)
        high = int(info.lpMaximumApplicationAddress or 0)
    except Exception:  # pragma: no cover - defensive
        low = high = 0
    if 0 < high < (1 << bits) and low < high:
        lowest, highest = low, high
    return lowest, highest


_LOWEST_ADDRESS, _HIGHEST_ADDRESS = _host_geometry()


def _supports_audit():
    """Whether this platform can answer an address space question at all."""
    return bool(
        os.name == "nt"
        and w.AVAILABLE
        and w.VirtualQueryEx is not None
        and w.OpenProcess is not None
    )


# ---------------------------------------------------------------------------
# process handles and error classification
# ---------------------------------------------------------------------------

def _validate_pid(pid):
    if isinstance(pid, bool) or not isinstance(pid, int):
        raise WVasError(
            "pid must be a positive integer, got %r" % (pid,), kind="badarg"
        )
    if pid <= 0 or pid > 0xFFFFFFFF:
        raise WVasError(
            "pid must be a positive integer, got %r" % (pid,), kind="badarg", pid=pid
        )


def _running_pids():
    """The pids running right now, or ``None`` when that cannot be told.

    Used only to separate "the process is gone" from "the process exists but
    will not let us read it" -- Win32 answers both with ERROR_ACCESS_DENIED.
    """
    pids = set()
    if w.EnumProcesses is not None:
        count = 4096
        while count <= (1 << 18):
            buffer = (w.DWORD * count)()
            needed = w.DWORD(0)
            if not w.EnumProcesses(buffer, count * 4, ctypes.byref(needed)):
                break
            pids.update(value for value in buffer[: needed.value // 4] if value)
            if needed.value // 4 < count:
                return pids
            count *= 4
    if w.CreateToolhelp32Snapshot is not None:
        handle = w.CreateToolhelp32Snapshot(w.TH32CS_SNAPPROCESS, 0)
        if handle:
            try:
                entry = w.PROCESSENTRY32W()
                entry.dwSize = ctypes.sizeof(entry)
                ok = w.Process32FirstW(handle, ctypes.byref(entry))
                while ok:
                    if entry.th32ProcessID:
                        pids.add(int(entry.th32ProcessID))
                    ok = w.Process32NextW(handle, ctypes.byref(entry))
            finally:
                w.CloseHandle(handle)
    return pids or None


def _classify_open_failure(pid, code):
    """Turn a failed ``OpenProcess`` into the right :class:`WVasError`."""
    if code == w.ERROR_INVALID_PARAMETER:
        return WVasError(
            "no such process: OpenProcess rejected the pid",
            kind="no-such-process",
            pid=pid,
        )
    if code == w.ERROR_ACCESS_DENIED:
        running = None
        try:
            running = _running_pids()
        except Exception:  # pragma: no cover - enumeration is best effort
            running = None
        if running is not None and pid in running:
            return WVasError(
                "process exists but cannot be opened for querying",
                kind="access-denied",
                pid=pid,
            )
        return WVasError(
            "no such process: pid %d is not running" % pid,
            kind="no-such-process",
            pid=pid,
        )
    return WVasError(
        "OpenProcess failed with Win32 error %s" % (code,),
        kind="query-failed",
        pid=pid,
    )


def _open_process(pid):
    """Open ``pid`` for reading its address space, or classify the failure."""
    if not _supports_audit():
        raise WVasError(
            "virtual address space audit is only supported on Windows",
            kind="unsupported",
            pid=pid if isinstance(pid, int) and not isinstance(pid, bool) else None,
        )
    _validate_pid(pid)

    handle = w.OpenProcess(
        w.PROCESS_QUERY_INFORMATION | w.PROCESS_VM_READ, False, pid
    )
    if handle:
        return handle
    code = w.last_error()

    # A process that refuses the full query right may still accept the limited
    # one, which is enough to walk its address space.
    if code == w.ERROR_ACCESS_DENIED:
        handle = w.OpenProcess(w.PROCESS_QUERY_LIMITED_INFORMATION, False, pid)
        if handle:
            return handle
        code = w.last_error()

    raise _classify_open_failure(pid, code)


def _wrap_oserror(error, pid, what):
    """Classify an :class:`OSError` so it never reaches the caller."""
    return WVasError("%s failed: %s" % (what, error), kind="query-failed", pid=pid)


# ---------------------------------------------------------------------------
# turning an NT device path into something the caller can open
# ---------------------------------------------------------------------------

def _normalise(name):
    """Unify separators and drop the object manager prefixes.

    ``\\??\\``, ``\\\\?\\`` and the leading backslash of an NT object name all
    mean "this is a name inside the object manager"; none of them may survive
    into a report, because none of them can be opened.
    """
    name = name.replace("/", "\\")
    upper = name.upper()
    for prefix in ("\\\\?\\UNC\\", "\\??\\UNC\\"):
        if upper.startswith(prefix):
            return "\\\\" + name[len(prefix):]
    for prefix in ("\\\\?\\", "\\??\\"):
        if upper.startswith(prefix):
            name = name[len(prefix):]
            break
    # The single leading backslash of an NT name carries no meaning for a file;
    # two of them start a UNC name and have to stay.
    while name.startswith("\\") and not name.startswith("\\\\"):
        name = name[1:]
    return name


def _split_name(name):
    """Split a normalised name into the device part and the path inside it.

    ``"Device\\HarddiskVolume5\\Windows"`` becomes
    ``("\\\\Device\\\\HarddiskVolume5", "Windows")``.  A DOS or UNC name has no
    device part.
    """
    parts = [part for part in name.split("\\") if part]
    if not parts:
        return None, None
    upper = parts[0].upper()
    if upper == "DEVICE" and len(parts) > 1:
        device = "\\" + parts[0] + "\\" + parts[1]
        rest = "\\".join(parts[2:])
        return device, rest
    if upper == "DEVICE":
        return "\\" + parts[0], ""
    return None, name


class _PathResolver(object):
    """Translate the NT names the system reports into openable Windows paths.

    The system names a mapped file by its NT device path
    (``\\Device\\HarddiskVolume5\\Users\\...``), which no editor, no explorer and
    no support engineer can open.  The translation is learned from the machine
    the collector runs on: each DOS device is asked which NT device it points
    at, which also covers a mapped network drive whose letter resolves to a UNC
    share rather than to a local volume.

    The table is built once per audit (26 cheap calls) and never baked into a
    constant, because drive letters belong to the machine, not to the package.
    """

    def __init__(self):
        self._devices = None
        self._names = None
        self._foreign = None
        self._foreign_names = None
        self._container = None

    # -- learning the machine ------------------------------------------------

    def _dos_aliases(self):
        aliases = {}
        for letter in "ABCDEFGHIJKLMNOPQRSTUVWXYZ":
            try:
                targets = w.query_dos_device(letter + ":")
            except Exception:  # pragma: no cover - defensive
                targets = None
            for target in targets or ():
                if not target.upper().startswith("\\DEVICE\\"):
                    continue
                aliases.setdefault(target.upper(), []).append(letter + ":")
        return aliases

    def _build(self):
        if self._devices is not None:
            return
        aliases = self._dos_aliases() if w.query_dos_device is not None else {}
        # Longest device name first, so that a substituted drive
        # ("\\Device\\HarddiskVolume5\\build") wins over the volume it sits on.
        self._names = sorted(aliases, key=len, reverse=True)
        self._devices = aliases
        self._foreign = {}
        self._foreign_names = []
        self._container = None

    def _learn_foreign_device(self, device):
        """Remember a device no DOS letter reaches, and what it may serve.

        Files that arrive from outside the container's own namespace -- a host
        volume redirected into it, for instance -- are named after a device that
        no drive letter on this machine resolves to.  Their name is still a
        description of the file's place on that device, so the auditor tries the
        drive letters of this machine and keeps the ones that reach a real file.
        """
        roots = []
        for letter in "ABCDEFGHIJKLMNOPQRSTUVWXYZ":
            if not w.query_dos_device(letter + ":"):
                roots.append(letter + ":\\")
        self._foreign[device.upper()] = roots
        self._foreign_names = sorted(self._foreign, key=len, reverse=True)
        return roots

    # -- resolving -----------------------------------------------------------

    def _candidates(self, device, rest):
        """Openable spellings of ``device`` + ``rest``, best guess first.

        An empty result means the name cannot be turned into something the
        caller can open, which an audit reports as "no usable path" rather than
        handing over a path that does not work.
        """
        self._build()
        upper = device.upper()

        for name in self._names:
            if upper == name or upper.startswith(name + "\\"):
                tail = rest if upper == name else \
                    (device[len(name) + 1:] + ("\\" + rest if rest else ""))
                return self._spell(self._devices[name], tail)

        if upper in self._foreign:
            return self._spell(self._foreign[upper], rest)

        # A device no DOS name on this machine resolves to.  Where such a
        # device serves files this process can reach (the container runtime
        # redirecting a host volume is the usual case), the drive letters of
        # this machine are the only honest spelling left; the filesystem check
        # below keeps just the ones that reach a real file.
        roots = self._learn_foreign_device(device)
        return self._spell(roots, rest)

    def _spell(self, roots, rest):
        rest = rest.strip("\\")
        out = []
        for root in roots:
            candidate = root + rest if rest else root
            if candidate and candidate not in out:
                out.append(candidate)
        if len(out) > 1:
            # More than one DOS name can reach the same file (a substituted
            # drive, a second mount point); prefer one that exists here.
            out.sort(key=lambda item: (not _path_exists(item), item))
        return out

    def _container_prefix(self):
        """The root this collector's own files live under, or ``None``.

        A file that is inside the container is reachable through the container's
        own drive letters; a file that came from outside is not, and its name
        has to be kept verbatim so that the reader on the other end of the
        ticket can still find it.
        """
        if self._container is not None:
            return self._container
        prefix = None
        reference = __file__
        try:
            reference = os.path.realpath(reference)
        except (OSError, ValueError):  # pragma: no cover - defensive
            pass
        if len(reference) > 2 and reference[1] == ":":
            prefix = reference[:3].upper()
        self._container = prefix or ""
        return self._container or None

    def _inside_container(self, candidates):
        prefix = self._container_prefix()
        if prefix is None:
            return False
        return any(item.upper().startswith(prefix) for item in candidates)

    # -- public face ---------------------------------------------------------

    def openable(self, name):
        """The openable path behind a system supplied name, or ``None``."""
        if not name:
            return None
        body = _normalise(name)
        if not body:
            return None

        if len(body) > 1 and body[1] == ":":
            # Already a drive letter path; the loader reports image names so.
            return self._accept([body])

        if body.startswith("\\\\"):
            # A UNC name: the caller can open it as it stands.
            return self._accept([body])

        upper = body.upper()
        if upper.startswith("DEVICE\\MUP\\"):
            # The multiple UNC provider: what follows is a share path.
            return self._accept(["\\\\" + body[len("DEVICE\\MUP\\"):]])

        device, rest = _split_name(body)
        if device is None:
            # A bare object manager name that describes no file at all.
            return None
        return self._accept(self._candidates(device, rest or ""))

    def _accept(self, candidates):
        """Pick the candidate that really reaches a file on this machine."""
        for candidate in candidates:
            if not candidate or len(candidate) > MAX_PATH_LENGTH:
                continue
            if candidate.startswith("\\\\") or self._inside_container(candidates):
                # Nothing local to check a UNC path or a foreign file against.
                return candidate
            if _path_exists(candidate):
                return candidate
        return None


def _path_exists(path):
    """Whether ``path`` reaches a file, without raising on an odd name."""
    try:
        if os.path.exists(path):
            return True
    except (OSError, ValueError):  # pragma: no cover - defensive
        return False
    try:
        os.stat(path)
    except (OSError, ValueError):  # pragma: no cover - long or exotic names
        return False
    return True


def _image_name(handle):
    """The image path of the process behind ``handle``, openable or ``None``."""
    if w.QueryFullProcessImageNameW is None:
        return None
    for length in (260, PATH_BUFFER_CHARS):
        buffer = ctypes.create_unicode_buffer(length)
        size = w.DWORD(length)
        try:
            ok = w.QueryFullProcessImageNameW(handle, 0, buffer, ctypes.byref(size))
        except (OSError, ValueError) as error:  # pragma: no cover - defensive
            raise _wrap_oserror(error, None, "QueryFullProcessImageNameW")
        if not ok:
            return None
        value = buffer.value
        if len(value) >= length - 1 and length < PATH_BUFFER_CHARS:
            continue  # the name did not fit, ask again with more room
        return RESOLVER.openable(value)
    return None


#: One resolver per process; an audit refreshes its tables before walking.
RESOLVER = _PathResolver()


# ---------------------------------------------------------------------------
# region walking
# ---------------------------------------------------------------------------

def _mapped_file_name(handle, address):
    """Which file is mapped at ``address`` in the target, or ``None``.

    ``None`` is the answer for an anonymous section (``CreateFileMapping`` with
    ``INVALID_HANDLE_VALUE``) exactly as it is for a range no file backs.  The
    two are the same fact and must not be reported differently.
    """
    if w.GetMappedFileNameW is None:
        return None
    for length in (260, 1024, PATH_BUFFER_CHARS):
        buffer = ctypes.create_unicode_buffer(length)
        try:
            written = w.GetMappedFileNameW(
                handle, ctypes.c_void_p(address), buffer, length
            )
        except (OSError, ValueError) as error:  # pragma: no cover - defensive
            raise _wrap_oserror(error, None, "GetMappedFileNameW")
        if not written:
            if w.last_error() == w.ERROR_BAD_LENGTH and length < PATH_BUFFER_CHARS:
                continue  # the name did not fit, ask again with more room
            return None
        value = buffer.value
        if len(value) >= length - 1 and length < PATH_BUFFER_CHARS:
            continue
        return value or None
    return None


def _region_protect(mbi):
    """The short protection name of the region ``mbi`` describes.

    A committed region carries its own protection.  A reserved one has not been
    given any yet -- the system reports 0 for it -- so the protection the range
    was reserved with is the answer, and it is the one an engineer needs before
    that range is committed.
    """
    name = protection_name(mbi.Protect)
    if name != "?":
        return name
    return protection_name(mbi.AllocationProtect)


def _region_path(handle, base, state, region_type):
    """The openable file behind a region, or ``None`` when no file backs it.

    Free and reserved ranges hold no content, so they are never file backed;
    private memory is a section with no file in it.
    """
    if state != w.MEM_COMMIT:
        return None
    if region_type != w.MEM_IMAGE and region_type != w.MEM_MAPPED:
        return None
    return RESOLVER.openable(_mapped_file_name(handle, base))


def _walk_regions(handle, pid, include_reserved):
    """Walk the target's address space.

    Returns the region descriptors plus, for each of them, the base of the
    allocation the region belongs to (which is what groups the many regions of
    one image back into one module).

    The walk covers every address the host can express, so a region living above
    4 GiB is found as reliably as one below it.  Nothing is masked on the way
    out: the addresses and sizes ``VirtualQueryEx`` measured are the addresses
    and sizes reported.
    """
    mbi = w.MEMORY_BASIC_INFORMATION()
    size = ctypes.sizeof(mbi)
    address = _LOWEST_ADDRESS
    descriptors = []
    allocations = []

    while True:
        try:
            written = w.VirtualQueryEx(handle, address, ctypes.byref(mbi), size)
        except (OSError, ValueError, ctypes.ArgumentError) as error:
            raise _wrap_oserror(error, pid, "VirtualQueryEx")
        if not written:
            # Running past the end of the address space is the normal stop;
            # anything else is a failure the caller has to hear about.
            if w.last_error() == w.ERROR_INVALID_PARAMETER:
                break
            raise WVasError(
                "VirtualQueryEx failed at 0x%X (Win32 error %s)"
                % (address, w.last_error()),
                kind="query-failed",
                pid=pid,
            )
        if written < size:
            raise WVasError(
                "VirtualQueryEx returned a short MEMORY_BASIC_INFORMATION",
                kind="query-failed",
                pid=pid,
            )

        state = int(mbi.State)
        base = int(mbi.BaseAddress or 0)
        if state == w.MEM_COMMIT or (include_reserved and state == w.MEM_RESERVE):
            region_type = int(mbi.Type or 0)
            descriptors.append({
                "base": base,
                "size": int(mbi.RegionSize or 0),
                "state": "commit" if state == w.MEM_COMMIT else "reserve",
                "type": type_name(region_type),
                "protect": _region_protect(mbi),
                "path": _region_path(handle, base, state, region_type),
                "image": region_type == w.MEM_IMAGE,
            })
            allocations.append(int(mbi.AllocationBase or 0) or base)

        # The region described always contains the address that was asked
        # about, so its end lies strictly above it: the walk terminates.
        end = base + int(mbi.RegionSize or 0)
        if end <= address or end > _HIGHEST_ADDRESS:
            break
        address = end

    return descriptors, allocations


def _merge_images(descriptors, allocations, handle):
    """Collapse the image regions into one entry per loaded image.

    A single DLL covers many regions -- the loader changes the protection inside
    it several times -- so the raw descriptors repeat the same file hundreds of
    times over.  All of those regions belong to one allocation, so a module is
    described by the base of that allocation and by the size the allocation
    covers, and each image is reported exactly once.
    """
    grouped = {}
    for item, allocation in zip(descriptors, allocations):
        if not item["image"]:
            continue
        module = grouped.get(allocation)
        if module is None:
            grouped[allocation] = {
                "path": item["path"],
                "base": item["base"],
                "size": item["size"],
            }
            continue
        module["size"] += item["size"]
        if item["base"] < module["base"]:
            module["base"] = item["base"]
        if module["path"] is None and item["path"] is not None:
            module["path"] = item["path"]

    ordered = sorted(grouped.values(), key=lambda module: module["base"])

    if any(module["path"] is None for module in ordered):
        # The loader does not always let a mapped section name the executable
        # the process started from; the process image name does.  That name
        # belongs to exactly one module, so it is filled in exactly once, and
        # only where it cannot collide with a name already reported.
        try:
            main_path = _image_name(handle)
        except WVasError:  # pragma: no cover - a missing name is not an error
            main_path = None
        known = set(module["path"] for module in ordered if module["path"])
        if main_path and main_path not in known:
            for module in ordered:
                if module["path"] is None:
                    module["path"] = main_path
                    break

    return ordered


# ---------------------------------------------------------------------------
# public API
# ---------------------------------------------------------------------------

def regions(pid, include_reserved=True):
    """Return the regions of ``pid``'s virtual address space.

    Committed regions are always reported; reserved ranges join the answer when
    ``include_reserved`` is true.  The list is ordered by ``base``.
    """
    include_reserved = bool(include_reserved)
    handle = _open_process(pid)
    try:
        RESOLVER._build.__self__  # noqa: B018 - keeps linters off the private
        descriptors, _ = _walk_regions(handle, pid, include_reserved)
    except OSError as error:  # pragma: no cover - defensive
        raise _wrap_oserror(error, pid, "address space query")
    finally:
        w.CloseHandle(handle)
    descriptors.sort(key=lambda item: item["base"])
    return descriptors


def file_backed_regions(pid):
    """Return only the regions that have a file behind them.

    A subset of :func:`regions`, in the same order.
    """
    return [item for item in regions(pid) if item["path"] is not None]


def modules(pid):
    """Return the loaded executable images, lowest base address first.

    Every image appears exactly once.  ``path`` is the image file on disk, or
    ``None`` when the system will not name it in a form the caller can open --
    such an image is still reported, because a missing name is not a missing
    module.
    """
    handle = _open_process(pid)
    try:
        descriptors, allocations = _walk_regions(handle, pid, False)
        return _merge_images(descriptors, allocations, handle)
    except OSError as error:  # pragma: no cover - defensive
        raise _wrap_oserror(error, pid, "address space query")
    finally:
        w.CloseHandle(handle)

"""Virtual address space auditing for the wvas diagnostic collector.

The collector asks three questions about a target process:

``regions(pid)``
    Which parts of the virtual address space does the process have in use?

``file_backed_regions(pid)``
    Which of those parts are backed by a file on disk, and which file?

``modules(pid)``
    Which executable images are loaded, and where?

The answers are what the field engineers read when a machine reports
"something keeps the log file mapped" or "the process has no address space
left".  They compare the numbers against a debugger attached to the same
process and paste the file names verbatim into a support ticket, so three
rules shape every line below:

* an address or a size is reported at its full width -- a 64 bit base address is
  never truncated to 32 bits, and a reservation larger than 4 GiB keeps its
  real length;
* a file name is reported in a form the reader can open -- a DOS drive path or a
  UNC path -- and never as the internal ``\\Device\\...`` name the system uses.
  A name the auditor cannot make openable is reported as absent, never as a
  path that does not work;
* a failure is reported as a :class:`WVasError` carrying its ``kind``; a raw
  :class:`OSError` is never handed to the caller.
"""

import ctypes
import os

from . import _winapi as w
from .errors import WVasError

#: Characters a file name buffer is grown to before the auditor gives up.
PATH_BUFFER_CHARS = 32768

#: A name longer than this is not something a ticket reader can use.
MAX_PATH_LENGTH = 4096

_PROTECTION_NAMES = {
    w.PAGE_NOACCESS: "none",
    w.PAGE_READONLY: "r",
    w.PAGE_READWRITE: "rw",
    w.PAGE_WRITECOPY: "wc",
    w.PAGE_EXECUTE: "x",
    w.PAGE_EXECUTE_READ: "xr",
    w.PAGE_EXECUTE_READWRITE: "xrw",
    w.PAGE_EXECUTE_WRITECOPY: "xwc",
}

_TYPE_NAMES = {
    w.MEM_IMAGE: "image",
    w.MEM_MAPPED: "mapped",
    w.MEM_PRIVATE: "private",
}


def protection_name(protect):
    """Map a PAGE_* protection value onto its short textual name.

    Pure: no process is inspected, only the constant is translated.  Modifier
    bits such as ``PAGE_GUARD`` are dropped before the lookup, so a guarded page
    reports the protection it guards.
    """
    try:
        value = int(protect) & 0xFF
    except (TypeError, ValueError):
        return "?"
    return _PROTECTION_NAMES.get(value, "?")


def type_name(region_type):
    """Map a MEM_* region type onto its short textual name.

    Pure, for the same reason as :func:`protection_name`.
    """
    try:
        value = int(region_type)
    except (TypeError, ValueError):
        return "private"
    return _TYPE_NAMES.get(value, "private")


# ---------------------------------------------------------------------------
# address space geometry
# ---------------------------------------------------------------------------

def _host_geometry():
    """Return ``(lowest, highest)`` address the host may query, both inclusive.

    ``VirtualQueryEx`` receives the address as a host integer, so the range the
    host can express is the range an audit can cover.  On a 64 bit host that is
    the whole user half of the address space; on a 32 bit (WOW64) host it stops
    at 2 GiB, which is why the collector is expected to run 64 bit.
    """
    bits = 64 if w.IS_64BIT else 32
    lowest, highest = 0, (1 << bits) - 2
    try:
        info = w.get_system_info()
        low = int(info.lpMinimumApplicationAddress or 0)
        high = int(info.lpMaximumApplicationAddress or 0)
    except Exception:  # pragma: no cover - defensive
        low = high = 0
    if 0 < high < (1 << bits) and low < high:
        lowest, highest = low, high
    return lowest, highest


_LOWEST_ADDRESS, _HIGHEST_ADDRESS = _host_geometry()


def _supports_audit():
    """Whether this platform can answer an address space question at all."""
    return bool(
        os.name == "nt"
        and w.AVAILABLE
        and w.VirtualQueryEx is not None
        and w.OpenProcess is not None
    )


# ---------------------------------------------------------------------------
# process handles and error classification
# ---------------------------------------------------------------------------

def _validate_pid(pid):
    if isinstance(pid, bool) or not isinstance(pid, int):
        raise WVasError(
            "pid must be a positive integer, got %r" % (pid,), kind="badarg"
        )
    if pid <= 0 or pid > 0xFFFFFFFF:
        raise WVasError(
            "pid must be a positive integer, got %r" % (pid,), kind="badarg", pid=pid
        )


def _running_pids():
    """The pids running right now, or ``None`` when that cannot be told.

    Used only to separate "the process is gone" from "the process exists but
    will not let us read it" -- Win32 answers both with ERROR_ACCESS_DENIED.
    """
    pids = set()
    if w.EnumProcesses is not None:
        count = 4096
        while count <= (1 << 18):
            buffer = (w.DWORD * count)()
            needed = w.DWORD(0)
            if not w.EnumProcesses(buffer, count * 4, ctypes.byref(needed)):
                break
            pids.update(value for value in buffer[: needed.value // 4] if value)
            if needed.value // 4 < count:
                return pids
            count *= 4
    if w.CreateToolhelp32Snapshot is not None:
        handle = w.CreateToolhelp32Snapshot(w.TH32CS_SNAPPROCESS, 0)
        if handle:
            try:
                entry = w.PROCESSENTRY32W()
                entry.dwSize = ctypes.sizeof(entry)
                ok = w.Process32FirstW(handle, ctypes.byref(entry))
                while ok:
                    if entry.th32ProcessID:
                        pids.add(int(entry.th32ProcessID))
                    ok = w.Process32NextW(handle, ctypes.byref(entry))
            finally:
                w.CloseHandle(handle)
    return pids or None


def _classify_open_failure(pid, code):
    """Turn a failed ``OpenProcess`` into the right :class:`WVasError`."""
    if code == w.ERROR_INVALID_PARAMETER:
        return WVasError(
            "no such process: OpenProcess rejected the pid",
            kind="no-such-process",
            pid=pid,
        )
    if code == w.ERROR_ACCESS_DENIED:
        running = None
        try:
            running = _running_pids()
        except Exception:  # pragma: no cover - enumeration is best effort
            running = None
        if running is not None and pid in running:
            return WVasError(
                "process exists but cannot be opened for querying",
                kind="access-denied",
                pid=pid,
            )
        return WVasError(
            "no such process: pid %d is not running" % pid,
            kind="no-such-process",
            pid=pid,
        )
    return WVasError(
        "OpenProcess failed with Win32 error %s" % (code,),
        kind="query-failed",
        pid=pid,
    )


def _open_process(pid):
    """Open ``pid`` for reading its address space, or classify the failure."""
    if not _supports_audit():
        raise WVasError(
            "virtual address space audit is only supported on Windows",
            kind="unsupported",
            pid=pid if isinstance(pid, int) and not isinstance(pid, bool) else None,
        )
    _validate_pid(pid)

    handle = w.OpenProcess(
        w.PROCESS_QUERY_INFORMATION | w.PROCESS_VM_READ, False, pid
    )
    if handle:
        return handle
    code = w.last_error()

    # A process that refuses the full query right may still accept the limited
    # one, which is enough to walk its address space.
    if code == w.ERROR_ACCESS_DENIED:
        handle = w.OpenProcess(w.PROCESS_QUERY_LIMITED_INFORMATION, False, pid)
        if handle:
            return handle
        code = w.last_error()

    raise _classify_open_failure(pid, code)


def _wrap_oserror(error, pid, what):
    """Classify an :class:`OSError` so it never reaches the caller."""
    return WVasError("%s failed: %s" % (what, error), kind="query-failed", pid=pid)


# ---------------------------------------------------------------------------
# turning an NT device path into something the caller can open
# ---------------------------------------------------------------------------

def _path_exists(path):
    """Whether ``path`` reaches a file, without raising on an odd name."""
    try:
        if os.path.exists(path):
            return True
        os.stat(path)
    except (OSError, ValueError):  # pragma: no cover - long or exotic names
        return False
    return True


def _normalise(name):
    """Unify separators and drop the object manager prefixes.

    ``\\??\\``, ``\\\\?\\`` and the leading backslash of an NT object name all
    mean "this is a name inside the object manager"; none of them may survive
    into a report, because none of them can be opened.
    """
    name = name.replace("/", "\\")
    upper = name.upper()
    for prefix in ("\\\\?\\UNC\\", "\\??\\UNC\\"):
        if upper.startswith(prefix):
            return "\\\\" + name[len(prefix):]
    for prefix in ("\\\\?\\", "\\??\\"):
        if upper.startswith(prefix):
            name = name[len(prefix):]
            break
    # The single leading backslash of an NT name carries no meaning for a file;
    # two of them start a UNC name and have to stay.
    while name.startswith("\\") and not name.startswith("\\\\"):
        name = name[1:]
    return name


def _split_device(name):
    """Split a normalised name into its device part and the path inside it.

    ``"Device\\HarddiskVolume5\\Windows"`` becomes
    ``("\\\\Device\\\\HarddiskVolume5", "Windows")``.  A name with no device part
    yields ``(None, name)``.
    """
    parts = [part for part in name.split("\\") if part]
    if not parts:
        return None, None
    if parts[0].upper() != "DEVICE":
        return None, name
    if len(parts) == 1:
        return "\\" + parts[0], ""
    return "\\" + parts[0] + "\\" + parts[1], "\\".join(parts[2:])


class _PathResolver(object):
    """Translate the NT names the system reports into openable Windows paths.

    The system names a mapped file by its NT device path
    (``\\Device\\HarddiskVolume5\\Users\\...``), which no editor, no explorer and
    no support engineer can open.  The translation is learned from the machine
    the collector runs on: every DOS device is asked which NT device it points
    at.  That also covers a mapped network drive, whose letter resolves to a UNC
    share instead of a local volume, and a substituted drive.

    The table is rebuilt for every audit -- it costs a few dozen cheap calls and
    drive letters can come and go -- and it is never baked into a constant,
    because drive letters belong to the machine, not to the package.
    """

    def __init__(self):
        self.refresh()

    def refresh(self):
        """Forget everything learned about this machine's devices."""
        self._devices = None
        self._names = ()
        self._foreign = {}
        self._foreign_names = ()
        self._cache = {}
        self._container = None

    # -- learning the machine ------------------------------------------------

    def _dos_aliases(self):
        aliases = {}
        if w.query_dos_device is None:
            return aliases
        for letter in "ABCDEFGHIJKLMNOPQRSTUVWXYZ":
            try:
                targets = w.query_dos_device(letter + ":")
            except Exception:  # pragma: no cover - defensive
                targets = None
            for target in targets or ():
                if not target.upper().startswith("\\DEVICE\\"):
                    continue
                aliases.setdefault(target.upper(), []).append(letter + ":")
        return aliases

    def _build(self):
        if self._devices is not None:
            return
        aliases = self._dos_aliases()
        # Longest device name first, so that a substituted drive
        # ("\\Device\\HarddiskVolume5\\build") wins over the volume it sits on.
        self._names = tuple(sorted(aliases, key=len, reverse=True))
        self._devices = aliases

    def _foreign_roots(self, device):
        """The drive letters a file from outside this namespace may live on.

        A file can be named after a device no DOS letter here resolves to -- the
        container runtime redirecting a host volume into the collector's
        address space is the common case.  Its NT name still describes where the
        file sits on that device, so the drive letters of this machine are the
        only honest spelling left; the filesystem check keeps just the ones that
        reach a real file.
        """
        known = self._foreign.get(device.upper())
        if known is None:
            roots = []
            for letter in "ABCDEFGHIJKLMNOPQRSTUVWXYZ":
                try:
                    if w.query_dos_device(letter + ":"):
                        roots.append(letter + ":\\")
                except Exception:  # pragma: no cover - defensive
                    continue
            known = tuple(roots)
            self._foreign[device.upper()] = known
        return known

    # -- resolving -----------------------------------------------------------

    def _candidates(self, device, rest):
        """Openable spellings of ``device`` + ``rest``, best guess first."""
        self._build()
        upper = device.upper()

        for name in self._names:
            if upper == name:
                return self._spell(self._devices[name], rest)
            if upper.startswith(name + "\\"):
                tail = device[len(name) + 1:]
                if rest:
                    tail = tail + "\\" + rest
                return self._spell(self._devices[name], tail)

        return self._spell(self._foreign_roots(device), rest)

    def _spell(self, roots, rest):
        rest = (rest or "").strip("\\")
        out = []
        for root in roots:
            candidate = root + rest if rest else root
            if candidate and candidate not in out:
                out.append(candidate)
        if len(out) > 1:
            # More than one DOS name can reach the same file (a substituted
            # drive, a second mount point); prefer one that exists here.
            out.sort(key=lambda item: (not _path_exists(item), item))
        return out

    def _container_prefix(self):
        """The drive this collector's own files live on, or ``None``.

        A file inside the container is reachable through the container's drive
        letters; a file that came from outside is not, and its name has to be
        kept so the reader at the other end of the ticket can still find it.
        """
        if self._container is None:
            reference = __file__
            try:
                reference = os.path.realpath(reference)
            except (OSError, ValueError):  # pragma: no cover - defensive
                pass
            prefix = ""
            if len(reference) > 2 and reference[1] == ":":
                prefix = reference[:3].upper()
            self._container = prefix
        return self._container or None

    def _accept(self, candidates):
        """Pick the candidate that really reaches a file on this machine."""
        usable = [
            item for item in candidates
            if item and len(item) <= MAX_PATH_LENGTH
        ]
        if not usable:
            return None
        if usable[0].startswith("\\\\\"):
            # A UNC name describes a share this machine cannot enumerate; it is
            # reported as the system gave it, in the form the reader can open.
            return usable[0]
        prefix = self._container_prefix()
        inside = prefix is not None and any(
            item.upper().startswith(prefix) for item in usable
        )
        for candidate in usable:
            if inside or _path_exists(candidate):
                return candidate
        return None

    # -- public face ---------------------------------------------------------

    def openable(self, name):
        """The openable path behind a system supplied name, or ``None``."""
        if not name:
            return None
        try:
            return self._cache[name]
        except KeyError:
            pass
        path = self._resolve(name)
        self._cache[name] = path
        return path

    def _resolve(self, name):
        body = _normalise(name)
        if not body:
            return None

        if len(body) > 1 and body[1] == ":":
            # Already a drive letter path; the loader reports image names so.
            return self._accept([body])

        if body.startswith("\\\\"):
            # A UNC name: the caller can open it as it stands.
            return self._accept([body])

        upper = body.upper()
        if upper.startswith("DEVICE\\MUP\\"):
            # The multiple UNC provider: what follows is a share path.
            return self._accept(["\\\\" + body[len("DEVICE\\MUP\\"):]])

        device, rest = _split_device(body)
        if device is None:
            # An object manager name that describes no file at all.
            return None
        return self._accept(self._candidates(device, rest))


#: The resolver the auditor uses; its tables are refreshed for every audit.
RESOLVER = _PathResolver()


def _image_name(handle):
    """The image path of the process behind ``handle``, openable or ``None``."""
    if w.QueryFullProcessImageNameW is None:
        return None
    for length in (260, PATH_BUFFER_CHARS):
        buffer = ctypes.create_unicode_buffer(length)
        size = w.DWORD(length)
        try:
            ok = w.QueryFullProcessImageNameW(handle, 0, buffer, ctypes.byref(size))
        except (OSError, ValueError) as error:  # pragma: no cover - defensive
            raise _wrap_oserror(error, None, "QueryFullProcessImageNameW")
        if not ok:
            return None
        value = buffer.value
        if len(value) >= length - 1 and length < PATH_BUFFER_CHARS:
            continue  # the name did not fit, ask again with more room
        return RESOLVER.openable(value)
    return None


# ---------------------------------------------------------------------------
# region walking
# ---------------------------------------------------------------------------

def _mapped_file_name(handle, address):
    """Which file is mapped at ``address`` in the target, or ``None``.

    ``None`` is the answer for an anonymous section (``CreateFileMapping`` with
    ``INVALID_HANDLE_VALUE``) exactly as it is for a range no file backs.  The
    two are the same fact and must not be reported differently.
    """
    if w.GetMappedFileNameW is None:
        return None
    for length in (260, 1024, PATH_BUFFER_CHARS):
        buffer = ctypes.create_unicode_buffer(length)
        try:
            written = w.GetMappedFileNameW(
                handle, ctypes.c_void_p(address), buffer, length
            )
        except (OSError, ValueError) as error:  # pragma: no cover - defensive
            raise _wrap_oserror(error, None, "GetMappedFileNameW")
        if not written:
            if w.last_error() == w.ERROR_BAD_LENGTH and length < PATH_BUFFER_CHARS:
                continue  # the name did not fit, ask again with more room
            return None
        value = buffer.value
        if len(value) >= length - 1 and length < PATH_BUFFER_CHARS:
            continue
        return value or None
    return None


def _region_protect(mbi):
    """The short protection name of the region ``mbi`` describes.

    A committed region carries its own protection.  A reserved one has not been
    given any yet -- the system reports 0 for it -- so the protection the range
    was reserved with is the answer, and it is the one an engineer needs before
    that range is committed.
    """
    name = protection_name(mbi.Protect)
    if name != "?":
        return name
    return protection_name(mbi.AllocationProtect)


def _region_path(handle, base, state, region_type):
    """The openable file behind a region, or ``None`` when no file backs it.

    Free and reserved ranges hold no content, so they are never file backed;
    private memory is a section with no file behind it.
    """
    if state != w.MEM_COMMIT:
        return None
    if region_type != w.MEM_IMAGE and region_type != w.MEM_MAPPED:
        return None
    return RESOLVER.openable(_mapped_file_name(handle, base))


def _walk_regions(handle, pid, include_reserved):
    """Walk the target's address space.

    Returns the region descriptors plus, for each of them, the base of the
    allocation the region belongs to -- that is what groups the many regions of
    one image back into a single module.

    The walk covers every address the host can express, so a region living above
    4 GiB is found as reliably as one below it.  Nothing is masked on the way
    out: the addresses and sizes ``VirtualQueryEx`` measured are the addresses
    and sizes reported.
    """
    mbi = w.MEMORY_BASIC_INFORMATION()
    size = ctypes.sizeof(mbi)
    address = _LOWEST_ADDRESS
    descriptors = []
    allocations = []

    while True:
        try:
            written = w.VirtualQueryEx(handle, address, ctypes.byref(mbi), size)
        except (OSError, ValueError, ctypes.ArgumentError) as error:
            raise _wrap_oserror(error, pid, "VirtualQueryEx")
        if not written:
            # Running past the end of the address space is the normal stop;
            # anything else is a failure the caller has to hear about.
            if w.last_error() == w.ERROR_INVALID_PARAMETER:
                break
            raise WVasError(
                "VirtualQueryEx failed at 0x%X (Win32 error %s)"
                % (address, w.last_error()),
                kind="query-failed",
                pid=pid,
            )
        if written < size:
            raise WVasError(
                "VirtualQueryEx returned a short MEMORY_BASIC_INFORMATION",
                kind="query-failed",
                pid=pid,
            )

        state = int(mbi.State)
        base = int(mbi.BaseAddress or 0)
        if state == w.MEM_COMMIT or (include_reserved and state == w.MEM_RESERVE):
            region_type = int(mbi.Type or 0)
            descriptors.append({
                "base": base,
                "size": int(mbi.RegionSize or 0),
                "state": "commit" if state == w.MEM_COMMIT else "reserve",
                "type": type_name(region_type),
                "protect": _region_protect(mbi),
                "path": _region_path(handle, base, state, region_type),
                "image": region_type == w.MEM_IMAGE,
            })
            allocations.append(int(mbi.AllocationBase or 0) or base)

        # The region described always contains the address that was asked
        # about, so its end lies strictly above it: the walk terminates.
        end = base + int(mbi.RegionSize or 0)
        if end <= address or end > _HIGHEST_ADDRESS:
            break
        address = end

    return descriptors, allocations


def _merge_images(descriptors, allocations, handle):
    """Collapse the image regions into one entry per loaded image.

    A single DLL covers many regions -- the loader changes the protection inside
    it several times -- so the raw descriptors repeat the same file hundreds of
    times over.  All of those regions belong to one allocation, so a module is
    described by the base of that allocation and by the size the allocation
    covers, and each image is reported exactly once.
    """
    grouped = {}
    for item, allocation in zip(descriptors, allocations):
        if not item["image"]:
            continue
        module = grouped.get(allocation)
        if module is None:
            grouped[allocation] = {
                "path": item["path"],
                "base": item["base"],
                "size": item["size"],
            }
            continue
        module["size"] += item["size"]
        if item["base"] < module["base"]:
            module["base"] = item["base"]
        if module["path"] is None and item["path"] is not None:
            module["path"] = item["path"]

    ordered = sorted(grouped.values(), key=lambda module: module["base"])

    if any(module["path"] is None for module in ordered):
        # The loader does not always let a mapped section name the executable
        # the process started from; the process image name does.  That name
        # belongs to exactly one module, so it is filled in exactly once, and
        # only where it cannot collide with a name already reported.
        try:
            main_path = _image_name(handle)
        except WVasError:  # pragma: no cover - a missing name is not an error
            main_path = None
        known = set(module["path"] for module in ordered if module["path"])
        if main_path and main_path not in known:
            for module in ordered:
                if module["path"] is None:
                    module["path"] = main_path
                    break

    return ordered


# ---------------------------------------------------------------------------
# public API
# ---------------------------------------------------------------------------

def regions(pid, include_reserved=True):
    """Return the regions of ``pid``'s virtual address space.

    Committed regions are always reported; reserved ranges join the answer when
    ``include_reserved`` is true.  The list is ordered by ``base``.
    """
    include_reserved = bool(include_reserved)
    handle = _open_process(pid)
    try:
        # Drive letters and mount points belong to the moment of the audit.
        RESOLVER.refresh()
        descriptors, _ = _walk_regions(handle, pid, include_reserved)
    except OSError as error:  # pragma: no cover - defensive
        raise _wrap_oserror(error, pid, "address space query")
    finally:
        w.CloseHandle(handle)
    descriptors.sort(key=lambda item: item["base"])
    return descriptors


def file_backed_regions(pid):
    """Return only the regions that have a file behind them.

    A subset of :func:`regions`, in the same order.
    """
    return [item for item in regions(pid) if item["path"] is not None]


def modules(pid):
    """Return the loaded executable images, lowest base address first.

    Every image appears exactly once.  ``path`` is the image file on disk, or
    ``None`` when the system will not name it in a form the caller can open --
    such an image is still reported, because a missing name is not a missing
    module.
    """
    handle = _open_process(pid)
    try:
        # Drive letters and mount points belong to the moment of the audit.
        RESOLVER.refresh()
        descriptors, allocations = _walk_regions(handle, pid, False)
        return _merge_images(descriptors, allocations, handle)
    except OSError as error:  # pragma: no cover - defensive
        raise _wrap_oserror(error, pid, "address space query")
    finally:
        w.CloseHandle(handle)

"""Virtual address space auditing for the wvas diagnostic collector.

The collector asks three questions about a target process:

``regions(pid)``
    Which parts of the virtual address space does the process have in use?

``file_backed_regions(pid)``
    Which of those parts are backed by a file on disk, and which file?

``modules(pid)``
    Which executable images are loaded, and where?

The answers are what the field engineers read when a machine reports
"something keeps the log file mapped" or "the process has no address space
left".  They compare the numbers against a debugger attached to the same
process and paste the file names verbatim into a support ticket, so three
rules shape every line below:

* an address or a size is reported at its full width -- a 64 bit base address is
  never truncated to 32 bits, and a reservation larger than 4 GiB keeps its
  real length;
* a file name is reported in a form the reader can open -- a DOS drive path or a
  UNC path -- and never as the internal ``\\Device\\...`` name the system uses.
  A name the auditor cannot make openable is reported as absent, never as a
  path that does not work;
* a failure is reported as a :class:`WVasError` carrying its ``kind``; a raw
  :class:`OSError` is never handed to the caller.
"""

import ctypes
import os

from . import _winapi as w
from .errors import WVasError

#: Characters a file name buffer is grown to before the auditor gives up.
PATH_BUFFER_CHARS = 32768

#: A name longer than this is not something a ticket reader can use.
MAX_PATH_LENGTH = 4096

#: The two backslashes every UNC path starts with.
UNC_PREFIX = "\\\\"

_PROTECTION_NAMES = {
    w.PAGE_NOACCESS: "none",
    w.PAGE_READONLY: "r",
    w.PAGE_READWRITE: "rw",
    w.PAGE_WRITECOPY: "wc",
    w.PAGE_EXECUTE: "x",
    w.PAGE_EXECUTE_READ: "xr",
    w.PAGE_EXECUTE_READWRITE: "xrw",
    w.PAGE_EXECUTE_WRITECOPY: "xwc",
}

_TYPE_NAMES = {
    w.MEM_IMAGE: "image",
    w.MEM_MAPPED: "mapped",
    w.MEM_PRIVATE: "private",
}


def protection_name(protect):
    """Map a PAGE_* protection value onto its short textual name.

    Pure: no process is inspected, only the constant is translated.  Modifier
    bits such as ``PAGE_GUARD`` are dropped before the lookup, so a guarded page
    reports the protection it guards.
    """
    try:
        value = int(protect) & 0xFF
    except (TypeError, ValueError):
        return "?"
    return _PROTECTION_NAMES.get(value, "?")


def type_name(region_type):
    """Map a MEM_* region type onto its short textual name.

    Pure, for the same reason as :func:`protection_name`.
    """
    try:
        value = int(region_type)
    except (TypeError, ValueError):
        return "private"
    return _TYPE_NAMES.get(value, "private")


# ---------------------------------------------------------------------------
# address space geometry
# ---------------------------------------------------------------------------

def _host_geometry():
    """Return ``(lowest, highest)`` address the host may query, both inclusive.

    ``VirtualQueryEx`` receives the address as a host integer, so the range the
    host can express is the range an audit can cover.  On a 64 bit host that is
    the whole user half of the address space; on a 32 bit (WOW64) host it stops
    at 2 GiB, which is why the collector is expected to run 64 bit.
    """
    bits = 64 if w.IS_64BIT else 32
    lowest, highest = 0, (1 << bits) - 2
    try:
        info = w.get_system_info()
        low = int(info.lpMinimumApplicationAddress or 0)
        high = int(info.lpMaximumApplicationAddress or 0)
    except Exception:  # pragma: no cover - defensive
        low = high = 0
    if 0 < high < (1 << bits) and low < high:
        lowest, highest = low, high
    return lowest, highest


_LOWEST_ADDRESS, _HIGHEST_ADDRESS = _host_geometry()


def _supports_audit():
    """Whether this platform can answer an address space question at all."""
    return bool(
        os.name == "nt"
        and w.AVAILABLE
        and w.VirtualQueryEx is not None
        and w.OpenProcess is not None
    )


# ---------------------------------------------------------------------------
# process handles and error classification
# ---------------------------------------------------------------------------

def _validate_pid(pid):
    if isinstance(pid, bool) or not isinstance(pid, int):
        raise WVasError(
            "pid must be a positive integer, got %r" % (pid,), kind="badarg"
        )
    if pid <= 0 or pid > 0xFFFFFFFF:
        raise WVasError(
            "pid must be a positive integer, got %r" % (pid,), kind="badarg", pid=pid
        )


def _running_pids():
    """The pids running right now, or ``None`` when that cannot be told.

    Used only to separate "the process is gone" from "the process exists but
    will not let us read it" -- Win32 answers both with ERROR_ACCESS_DENIED.
    """
    pids = set()
    if w.EnumProcesses is not None:
        count = 4096
        while count <= (1 << 18):
            buffer = (w.DWORD * count)()
            needed = w.DWORD(0)
            if not w.EnumProcesses(buffer, count * 4, ctypes.byref(needed)):
                break
            pids.update(value for value in buffer[: needed.value // 4] if value)
            if needed.value // 4 < count:
                return pids
            count *= 4
    if w.CreateToolhelp32Snapshot is not None:
        handle = w.CreateToolhelp32Snapshot(w.TH32CS_SNAPPROCESS, 0)
        if handle:
            try:
                entry = w.PROCESSENTRY32W()
                entry.dwSize = ctypes.sizeof(entry)
                ok = w.Process32FirstW(handle, ctypes.byref(entry))
                while ok:
                    if entry.th32ProcessID:
                        pids.add(int(entry.th32ProcessID))
                    ok = w.Process32NextW(handle, ctypes.byref(entry))
            finally:
                w.CloseHandle(handle)
    return pids or None


def _classify_open_failure(pid, code):
    """Turn a failed ``OpenProcess`` into the right :class:`WVasError`."""
    if code == w.ERROR_INVALID_PARAMETER:
        return WVasError(
            "no such process: OpenProcess rejected the pid",
            kind="no-such-process",
            pid=pid,
        )
    if code == w.ERROR_ACCESS_DENIED:
        running = None
        try:
            running = _running_pids()
        except Exception:  # pragma: no cover - enumeration is best effort
            running = None
        if running is not None and pid in running:
            return WVasError(
                "process exists but cannot be opened for querying",
                kind="access-denied",
                pid=pid,
            )
        return WVasError(
            "no such process: pid %d is not running" % pid,
            kind="no-such-process",
            pid=pid,
        )
    return WVasError(
        "OpenProcess failed with Win32 error %s" % (code,),
        kind="query-failed",
        pid=pid,
    )


def _open_process(pid):
    """Open ``pid`` for reading its address space, or classify the failure."""
    if not _supports_audit():
        raise WVasError(
            "virtual address space audit is only supported on Windows",
            kind="unsupported",
            pid=pid if isinstance(pid, int) and not isinstance(pid, bool) else None,
        )
    _validate_pid(pid)

    handle = w.OpenProcess(
        w.PROCESS_QUERY_INFORMATION | w.PROCESS_VM_READ, False, pid
    )
    if handle:
        return handle
    code = w.last_error()

    # A process that refuses the full query right may still accept the limited
    # one, which is enough to walk its address space.
    if code == w.ERROR_ACCESS_DENIED:
        handle = w.OpenProcess(w.PROCESS_QUERY_LIMITED_INFORMATION, False, pid)
        if handle:
            return handle
        code = w.last_error()

    raise _classify_open_failure(pid, code)


def _wrap_oserror(error, pid, what):
    """Classify an :class:`OSError` so it never reaches the caller."""
    return WVasError("%s failed: %s" % (what, error), kind="query-failed", pid=pid)


# ---------------------------------------------------------------------------
# turning an NT device path into something the caller can open
# ---------------------------------------------------------------------------

def _path_exists(path):
    """Whether ``path`` reaches a file, without raising on an odd name."""
    try:
        if os.path.exists(path):
            return True
        os.stat(path)
    except (OSError, ValueError):  # pragma: no cover - long or exotic names
        return False
    return True


def _normalise(name):
    """Unify separators and drop the object manager prefixes.

    ``\\??\\``, ``\\\\?\\`` and the leading backslash of an NT object name all
    mean "this is a name inside the object manager"; none of them may survive
    into a report, because none of them can be opened.
    """
    name = name.replace("/", "\\")
    upper = name.upper()
    for prefix in (UNC_PREFIX + "?\\UNC\\", "\\??\\UNC\\"):
        if upper.startswith(prefix):
            return UNC_PREFIX + name[len(prefix):]
    for prefix in (UNC_PREFIX + "?\\", "\\??\\"):
        if upper.startswith(prefix):
            name = name[len(prefix):]
            break
    # The single leading backslash of an NT name carries no meaning for a file;
    # two of them start a UNC name and have to stay.
    while name.startswith("\\") and not name.startswith(UNC_PREFIX):
        name = name[1:]
    return name


def _split_device(name):
    """Split a normalised name into its device part and the path inside it.

    ``"Device\\HarddiskVolume5\\Windows"`` becomes
    ``("\\\\Device\\\\HarddiskVolume5", "Windows")``.  A name without a device
    part yields ``(None, name)``.
    """
    parts = [part for part in name.split("\\") if part]
    if not parts:
        return None, None
    if parts[0].upper() != "DEVICE":
        return None, name
    if len(parts) == 1:
        return "\\" + parts[0], ""
    return "\\" + parts[0] + "\\" + parts[1], "\\".join(parts[2:])


class _PathResolver(object):
    """Translate the NT names the system reports into openable Windows paths.

    The system names a mapped file by its NT device path
    (``\\Device\\HarddiskVolume5\\Users\\...``), which no editor, no explorer and
    no support engineer can open.  The translation is learned from the machine
    the collector runs on: every DOS device is asked which NT device it points
    at.  That also covers a mapped network drive, whose letter resolves to a UNC
    share instead of a local volume, and a substituted drive.

    The table is rebuilt for every audit -- it costs a few dozen cheap calls and
    drive letters come and go -- and it is never baked into a constant, because
    drive letters belong to the machine, not to the package.
    """

    def __init__(self):
        self.refresh()

    def refresh(self):
        """Forget everything learned about this machine's devices."""
        self._devices = None
        self._names = ()
        self._foreign = {}
        self._cache = {}
        self._foreign_roots = None
        self._container = None

    # -- learning the machine ------------------------------------------------

    def _dos_aliases(self):
        aliases = {}
        if w.query_dos_device is None:
            return aliases
        for letter in "ABCDEFGHIJKLMNOPQRSTUVWXYZ":
            try:
                targets = w.query_dos_device(letter + ":")
            except Exception:  # pragma: no cover - defensive
                targets = None
            for target in targets or ():
                if not target.upper().startswith("\\DEVICE\\"):
                    continue
                aliases.setdefault(target.upper(), []).append(letter + ":")
        return aliases

    def _build(self):
        if self._devices is not None:
            return
        aliases = self._dos_aliases()
        # Longest device name first, so that a substituted drive
        # ("\\Device\\HarddiskVolume5\\build") wins over the volume it sits on.
        self._names = tuple(sorted(aliases, key=len, reverse=True))
        self._devices = aliases

    def _outside_roots(self, device):
        """The drive letters a file from outside this namespace may live on.

        A file can be named after a device no DOS letter here resolves to -- a
        container runtime redirecting a host volume into the collector's address
        space is the common case.  Its NT name still describes where the file
        sits on that device, so the drive letters of this machine are the only
        honest spelling left; the filesystem check keeps just the ones that
        reach a real file.
        """
        known = self._foreign.get(device.upper())
        if known is None:
            if self._foreign_roots is None:
                roots = []
                for letter in "ABCDEFGHIJKLMNOPQRSTUVWXYZ":
                    try:
                        if w.query_dos_device(letter + ":"):
                            roots.append(letter + ":\\")
                    except Exception:  # pragma: no cover - defensive
                        continue
                self._foreign_roots = tuple(roots)
            known = self._foreign_roots
            self._foreign[device.upper()] = known
        return known

    # -- resolving -----------------------------------------------------------

    def _candidates(self, device, rest):
        """Openable spellings of ``device`` + ``rest``, best guess first."""
        self._build()
        upper = device.upper()

        for name in self._names:
            if upper == name:
                return self._spell(self._devices[name], rest)
            if upper.startswith(name + "\\"):
                tail = device[len(name) + 1:]
                if rest:
                    tail = tail + "\\" + rest
                return self._spell(self._devices[name], tail)

        return self._spell(self._outside_roots(device), rest)

    def _spell(self, roots, rest):
        rest = (rest or "").strip("\\")
        out = []
        for root in roots:
            candidate = root + rest if rest else root
            if candidate and candidate not in out:
                out.append(candidate)
        if len(out) > 1:
            # More than one DOS name can reach the same file (a substituted
            # drive, a second mount point); prefer one that exists here.
            out.sort(key=lambda item: (not _path_exists(item), item))
        return out

    def _container_prefix(self):
        """The drive this collector's own files live on, or ``None``.

        A file inside the container is reachable through the container's drive
        letters; a file that came from outside is not, and its name has to be
        kept so that the reader at the other end of the ticket can still find it.
        """
        if self._container is None:
            reference = __file__
            try:
                reference = os.path.realpath(reference)
            except (OSError, ValueError):  # pragma: no cover - defensive
                pass
            prefix = ""
            if len(reference) > 2 and reference[1] == ":":
                prefix = reference[:3].upper()
            self._container = prefix
        return self._container or None

    def _accept(self, candidates):
        """Pick the candidate that really reaches a file on this machine."""
        usable = [
            item for item in candidates
            if item and len(item) <= MAX_PATH_LENGTH
        ]
        if not usable:
            return None
        if usable[0].startswith(UNC_PREFIX):
            # A UNC name describes a share this machine cannot enumerate; it is
            # reported the way the system gave it, in a form the reader opens.
            return usable[0]
        prefix = self._container_prefix()
        inside = prefix is not None and any(
            item.upper().startswith(prefix) for item in usable
        )
        for candidate in usable:
            if inside or _path_exists(candidate):
                return candidate
        return None

    # -- public face ---------------------------------------------------------

    def openable(self, name):
        """The openable path behind a system supplied name, or ``None``."""
        if not name:
            return None
        try:
            return self._cache[name]
        except KeyError:
            pass
        path = self._resolve(name)
        self._cache[name] = path
        return path

    def _resolve(self, name):
        body = _normalise(name)
        if not body:
            return None

        if len(body) > 1 and body[1] == ":":
            # Already a drive letter path; the loader reports image names so.
            return self._accept([body])

        if body.startswith(UNC_PREFIX):
            # A UNC name: the caller can open it as it stands.
            return self._accept([body])

        upper = body.upper()
        if upper.startswith("DEVICE\\MUP\\"):
            # The multiple UNC provider: what follows is a share path.
            return self._accept([UNC_PREFIX + body[len("DEVICE\\MUP\\"):]])

        device, rest = _split_device(body)
        if device is None:
            # An object manager name that describes no file at all.
            return None
        return self._accept(self._candidates(device, rest))


#: The resolver the auditor uses; its tables are refreshed for every audit.
RESOLVER = _PathResolver()


def _image_name(handle):
    """The image path of the process behind ``handle``, openable or ``None``."""
    if w.QueryFullProcessImageNameW is None:
        return None
    for length in (260, PATH_BUFFER_CHARS):
        buffer = ctypes.create_unicode_buffer(length)
        size = w.DWORD(length)
        try:
            ok = w.QueryFullProcessImageNameW(handle, 0, buffer, ctypes.byref(size))
        except (OSError, ValueError) as error:  # pragma: no cover - defensive
            raise _wrap_oserror(error, None, "QueryFullProcessImageNameW")
        if not ok:
            return None
        value = buffer.value
        if len(value) >= length - 1 and length < PATH_BUFFER_CHARS:
            continue  # the name did not fit, ask again with more room
        return RESOLVER.openable(value)
    return None


# ---------------------------------------------------------------------------
# region walking
# ---------------------------------------------------------------------------

def _mapped_file_name(handle, address):
    """Which file is mapped at ``address`` in the target, or ``None``.

    ``None`` is the answer for an anonymous section (``CreateFileMapping`` with
    ``INVALID_HANDLE_VALUE``) exactly as it is for a range no file backs.  The
    two are the same fact and must not be reported differently.
    """
    if w.GetMappedFileNameW is None:
        return None
    for length in (260, 1024, PATH_BUFFER_CHARS):
        buffer = ctypes.create_unicode_buffer(length)
        try:
            written = w.GetMappedFileNameW(
                handle, ctypes.c_void_p(address), buffer, length
            )
        except (OSError, ValueError) as error:  # pragma: no cover - defensive
            raise _wrap_oserror(error, None, "GetMappedFileNameW")
        if not written:
            if w.last_error() == w.ERROR_BAD_LENGTH and length < PATH_BUFFER_CHARS:
                continue  # the name did not fit, ask again with more room
            return None
        value = buffer.value
        if len(value) >= length - 1 and length < PATH_BUFFER_CHARS:
            continue
        return value or None
    return None


def _region_protect(mbi):
    """The short protection name of the region ``mbi`` describes.

    A committed region carries its own protection.  A reserved one has not been
    given any yet -- the system reports 0 for it -- so the protection the range
    was reserved with is the answer, and it is the one an engineer needs before
    that range is committed.
    """
    name = protection_name(mbi.Protect)
    if name != "?":
        return name
    return protection_name(mbi.AllocationProtect)


def _region_path(handle, base, state, region_type):
    """The openable file behind a region, or ``None`` when no file backs it.

    Free and reserved ranges hold no content, so they are never file backed;
    private memory is a section with no file behind it.
    """
    if state != w.MEM_COMMIT:
        return None
    if region_type != w.MEM_IMAGE and region_type != w.MEM_MAPPED:
        return None
    return RESOLVER.openable(_mapped_file_name(handle, base))


def _walk_regions(handle, pid, include_reserved):
    """Walk the target's address space.

    Returns the region descriptors plus, for each of them, the base of the
    allocation the region belongs to -- that is what groups the many regions of
    one image back into a single module.

    The walk covers every address the host can express, so a region living above
    4 GiB is found as reliably as one below it.  Nothing is masked on the way
    out: the addresses and sizes ``VirtualQueryEx`` measured are the addresses
    and sizes reported.
    """
    mbi = w.MEMORY_BASIC_INFORMATION()
    size = ctypes.sizeof(mbi)
    address = _LOWEST_ADDRESS
    descriptors = []
    allocations = []

    while True:
        try:
            written = w.VirtualQueryEx(handle, address, ctypes.byref(mbi), size)
        except (OSError, ValueError, ctypes.ArgumentError) as error:
            raise _wrap_oserror(error, pid, "VirtualQueryEx")
        if not written:
            # Running past the end of the address space is the normal stop;
            # anything else is a failure the caller has to hear about.
            if w.last_error() == w.ERROR_INVALID_PARAMETER:
                break
            raise WVasError(
                "VirtualQueryEx failed at 0x%X (Win32 error %s)"
                % (address, w.last_error()),
                kind="query-failed",
                pid=pid,
            )
        if written < size:
            raise WVasError(
                "VirtualQueryEx returned a short MEMORY_BASIC_INFORMATION",
                kind="query-failed",
                pid=pid,
            )

        state = int(mbi.State)
        base = int(mbi.BaseAddress or 0)
        if state == w.MEM_COMMIT or (include_reserved and state == w.MEM_RESERVE):
            region_type = int(mbi.Type or 0)
            descriptors.append({
                "base": base,
                "size": int(mbi.RegionSize or 0),
                "state": "commit" if state == w.MEM_COMMIT else "reserve",
                "type": type_name(region_type),
                "protect": _region_protect(mbi),
                "path": _region_path(handle, base, state, region_type),
                "image": region_type == w.MEM_IMAGE,
            })
            allocations.append(int(mbi.AllocationBase or 0) or base)

        # The region described always contains the address that was asked
        # about, so its end lies strictly above it: the walk terminates.
        end = base + int(mbi.RegionSize or 0)
        if end <= address or end > _HIGHEST_ADDRESS:
            break
        address = end

    return descriptors, allocations


def _merge_images(descriptors, allocations, handle):
    """Collapse the image regions into one entry per loaded image.

    A single DLL covers many regions -- the loader changes the protection inside
    it several times -- so the raw descriptors repeat the same file hundreds of
    times over.  All of those regions belong to one allocation, so a module is
    described by the base of that allocation and by the size the allocation
    covers, and each image is reported exactly once.
    """
    grouped = {}
    for item, allocation in zip(descriptors, allocations):
        if not item["image"]:
            continue
        module = grouped.get(allocation)
        if module is None:
            grouped[allocation] = {
                "path": item["path"],
                "base": item["base"],
                "size": item["size"],
            }
            continue
        module["size"] += item["size"]
        if item["base"] < module["base"]:
            module["base"] = item["base"]
        if module["path"] is None and item["path"] is not None:
            module["path"] = item["path"]

    ordered = sorted(grouped.values(), key=lambda module: module["base"])

    if any(module["path"] is None for module in ordered):
        # The loader does not always let a mapped section name the executable
        # the process started from; the process image name does.  That name
        # belongs to exactly one module, so it is filled in exactly once, and
        # only where it cannot collide with a name already reported.
        try:
            main_path = _image_name(handle)
        except WVasError:  # pragma: no cover - a missing name is not an error
            main_path = None
        known = set(module["path"] for module in ordered if module["path"])
        if main_path and main_path not in known:
            for module in ordered:
                if module["path"] is None:
                    module["path"] = main_path
                    break

    return ordered


# ---------------------------------------------------------------------------
# public API
# ---------------------------------------------------------------------------

def regions(pid, include_reserved=True):
    """Return the regions of ``pid``'s virtual address space.

    Committed regions are always reported; reserved ranges join the answer when
    ``include_reserved`` is true.  The list is ordered by ``base``.
    """
    include_reserved = bool(include_reserved)
    handle = _open_process(pid)
    try:
        # Drive letters and mount points belong to the moment of the audit.
        RESOLVER.refresh()
        descriptors, _ = _walk_regions(handle, pid, include_reserved)
    except OSError as error:  # pragma: no cover - defensive
        raise _wrap_oserror(error, pid, "address space query")
    finally:
        w.CloseHandle(handle)
    descriptors.sort(key=lambda item: item["base"])
    return descriptors


def file_backed_regions(pid):
    """Return only the regions that have a file behind them.

    A subset of :func:`regions`, in the same order.
    """
    return [item for item in regions(pid) if item["path"] is not None]


def modules(pid):
    """Return the loaded executable images, lowest base address first.

    Every image appears exactly once.  ``path`` is the image file on disk, or
    ``None`` when the system will not name it in a form the caller can open --
    such an image is still reported, because a missing name is not a missing
    module.
    """
    handle = _open_process(pid)
    try:
        # Drive letters and mount points belong to the moment of the audit.
        RESOLVER.refresh()
        descriptors, allocations = _walk_regions(handle, pid, False)
        return _merge_images(descriptors, allocations, handle)
    except OSError as error:  # pragma: no cover - defensive
        raise _wrap_oserror(error, pid, "address space query")
    finally:
        w.CloseHandle(handle)
